/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A44 staging source: frozen manifest heartbeat–hero; audit and publish every 20 lemmas. */
'use strict';
const D=globalThis.RA.D;
const E=(origin,word)=>({origin,prefix:null,root:null,suffix:null,history:[],formationLogic:'',mnemonic:null,note:'Claims are limited to the stated formation; uncertain history is left open.',source:'Etymonline — https://www.etymonline.com/word/'+word.toLowerCase()});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({wrong,right,reason,errorType});
const Q=(w,n,s,prompt,a,b,c,answer,explain,errorType='meaning')=>({id:w+'.q'+n,senseId:w+'.s'+s,errorType,type:'辨义与用法',prompt,options:[a,b,c],answer,explain});

D('heartbeat',{etymology:E('Heartbeat combines heart and beat. It names the rhythmic contractions of the heart that circulate blood through the body.','heartbeat'),contexts:[C('heartbeat.s1','急救培训','The nurse checked the runner’s heartbeat after the collapse and called for emergency support when she could not detect a pulse.','跑步者倒下后，护士检查了他的心跳；无法测到脉搏时，她呼叫了急救支援。','The nurse checked the runner’s heartbeat / after the collapse / and called for emergency support / when she could not detect a pulse.','heartbeat 指心脏有节律的搏动。','检查心跳是否存在是急救评估的一部分。')],mistakes:[M('The monitor showed no heartbeat, yet the patient’s heart was beating steadily and a strong pulse was present.','The monitor showed a steady heartbeat and a strong pulse.','稳定脉搏与监视器显示没有心跳相互矛盾。')],quiz:[Q('heartbeat',1,1,'A heartbeat is the?','rhythmic beating of the heart','movement of the lungs only','sound of a person’s footsteps','rhythmic beating of the heart','heartbeat 指心脏搏动。'),Q('heartbeat',2,1,'A pulse check helps assess whether a person has a?','heartbeat','handwriting style','hearth','heartbeat','脉搏可反映心脏是否在搏动。'),Q('heartbeat',3,1,'A monitor records changes in?','the heart’s beating rhythm','the size of a hectare','the height of a hedge','the heart’s beating rhythm','心电监护关注心脏活动。'),Q('heartbeat',4,1,'Which phrase is natural?','a rapid heartbeat after a sprint','a hectare heartbeat of farmland','a hedge heartbeat along the road','a rapid heartbeat after a sprint','运动后心跳加快是自然搭配。')]});
D('heartbreak',{etymology:E('Heartbreak combines heart and break as a figurative image of intense emotional pain. It means overwhelming grief or disappointment.','heartbreak'),contexts:[C('heartbreak.s1','个人经历','The cancellation of the long-awaited reunion was a heartbreak for the siblings, who had spent months arranging travel from different countries.','期盼已久的团聚被取消，对这对兄妹来说是巨大的失望；他们为此从不同国家安排了数月行程。','The cancellation of the long-awaited reunion / was a heartbreak for the siblings / who had spent months / arranging travel from different countries.','heartbreak 指压倒性的悲痛或失望。','长时间筹备的团聚被取消，带来强烈失望。')],mistakes:[M('The reunion’s cancellation brought no heartbreak because the siblings were devastated and could not stop crying.','The reunion’s cancellation caused heartbreak because the siblings were devastated.','极度悲痛与“没有心碎”直接矛盾。')],quiz:[Q('heartbreak',1,1,'Heartbreak is?','overwhelming grief or disappointment','a warm fireplace floor','a unit of land area','overwhelming grief or disappointment','heartbreak 指强烈悲痛或失望。'),Q('heartbreak',2,1,'Which event could cause heartbreak?','a deeply loved project suddenly ending','a comfortable meal after work','a hedge growing in spring','a deeply loved project suddenly ending','重要之物突然失去可能带来心碎之痛。'),Q('heartbreak',3,1,'The word heartbreak uses a physical image to describe?','emotional pain','body temperature','a medical heartbeat','emotional pain','心碎是情感痛苦的比喻。'),Q('heartbreak',4,1,'A person may describe a major disappointment as?','heartbreak','hectare','heater','heartbreak','该词也可指巨大的失望。')]});
D('heartfelt',{etymology:E('Heartfelt combines heart with felt, the past participle of feel. It describes words or emotions that are sincere and deeply felt.','heartfelt'),contexts:[C('heartfelt.s2','致谢发言','At the memorial, the daughter’s heartfelt thanks moved the volunteers who had cared for her father during his final months.','追悼会上，女儿真挚的谢意打动了在父亲生命最后几个月照料他的志愿者。','At the memorial / the daughter’s heartfelt thanks / moved the volunteers / who had cared for her father during his final months.','heartfelt 在此修饰 thanks，表示真情流露。','感谢内容带有真实而深切的情感，符合 s2。')],mistakes:[M('His heartfelt apology was insincere and delivered only as a joke, with no real feeling behind it.','His mocking remark was insincere and delivered as a joke, with no real feeling behind it.','没有真实情感、只是玩笑的话不属于 heartfelt apology。')],quiz:[Q('heartfelt',1,1,'A heartfelt apology is?','sincere and deeply felt','written only to meet a deadline','a measurement of heart rate','sincere and deeply felt','s1 指真诚、深切的。'),Q('heartfelt',2,2,'Heartfelt thanks are?','expressed with genuine emotion','offered without any feeling','a type of heater','expressed with genuine emotion','s2 强调表达或感受到真实情绪。'),Q('heartfelt',3,1,'Which comment sounds heartfelt?','“I truly appreciate how you stayed to help.”','“I am saying this only because someone told me to.”','“I do not care what happened.”','“I truly appreciate how you stayed to help.”','明确表达真实感谢，符合真挚之义。'),Q('heartfelt',4,1,'The compound heartfelt suggests a feeling that comes from?','the heart, sincerely','a measuring instrument','a hedge boundary','the heart, sincerely','该复合词以 heart 作情感来源的比喻。','word-formation')]});
D('hearth',{etymology:E('Hearth comes from Old English heorð and related Germanic words for a fireplace or the floor at its base. It names the area immediately around a domestic fireplace.','hearth'),contexts:[C('hearth.s1','老屋修缮','The family laid a fireproof stone hearth in front of the wood stove so stray embers would not land on the timber floor.','一家人在柴炉前铺设了防火石质炉床，避免火星落到木地板上。','The family laid a fireproof stone hearth / in front of the wood stove / so stray embers / would not land on the timber floor.','hearth 指壁炉或炉子前方的地面区域。','石质炉床承接火星，符合该词义。')],mistakes:[M('They installed a hearth on the roof of the house, far from the fireplace and its opening.','They installed a hearth on the floor in front of the fireplace.','炉床位于壁炉前的地面，不是屋顶。')],quiz:[Q('hearth',1,1,'A hearth is the floor area near a?','fireplace','hedge','telephone','fireplace','hearth 指壁炉前的地面。'),Q('hearth',2,1,'A stone hearth helps protect a room from?','sparks from the fire','a low heartbeat','a household heater’s handbook','sparks from the fire','炉床可防止火星落到可燃地面。'),Q('hearth',3,1,'Where would you expect to find a hearth?','at the base of a fireplace','in the middle of a field measured in hectares','on a hedgehog’s back','at the base of a fireplace','它紧邻壁炉底部。'),Q('hearth',4,1,'The old word hearth is related to?','a domestic fireplace','a medical fever','a musical instrument','a domestic fireplace','词源指家庭火炉区域。')]});
D('heartless',{etymology:E('Heartless combines heart and -less. Figuratively it describes someone or something cruel, cold, or lacking compassion.','heartless'),contexts:[C('heartless.s1','慈善决策','The company’s heartless decision to cancel shelter funding during a freezing week left hundreds of families without a safe place to sleep.','公司在严寒一周中取消收容所资金，这个冷酷决定使数百个家庭失去安全过夜的地方。','The company’s heartless decision / to cancel shelter funding during a freezing week / left hundreds of families / without a safe place to sleep.','heartless 修饰 decision，批评其缺乏同情心。','在严寒时取消急需援助，对受影响家庭冷酷无情。')],mistakes:[M('The heartless volunteer showed deep compassion by arranging emergency beds for every family in need.','The compassionate volunteer showed care by arranging emergency beds for every family in need.','积极帮助困难家庭体现同情心，与 heartless 相反。')],quiz:[Q('heartless',1,1,'A heartless response is?','cruel and lacking compassion','warm and deeply kind','a strong heartbeat','cruel and lacking compassion','heartless 指冷酷无情。'),Q('heartless',2,1,'Which decision might be called heartless?','rejecting urgent aid for families in freezing weather','opening a shelter during a storm','listening carefully to a worried person','rejecting urgent aid for families in freezing weather','拒绝急需援助显示缺乏同情。'),Q('heartless',3,1,'The suffix -less in heartless means?','without','full of','able to measure','without','-less 表示缺少或没有。','word-formation'),Q('heartless',4,1,'A heartless remark is likely to?','hurt someone without concern for their feelings','comfort a grieving friend','offer sincere thanks','hurt someone without concern for their feelings','该词形容不顾他人感受的冷酷言行。')]});
D('hearty',{etymology:E('Hearty is formed from heart plus -y and developed senses of warmth, sincerity, and strength. It describes something warm and strong in feeling or manner.','hearty'),contexts:[C('hearty.s1','问候方式','The hosts gave the tired hikers a hearty welcome, offering warm smiles and a place by the fire before asking about the trail.','主人热情地欢迎疲惫的徒步者，先给他们温暖的笑容和炉边座位，再询问路况。','The hosts gave the tired hikers a hearty welcome / offering warm smiles / and a place by the fire / before asking about the trail.','hearty 修饰 welcome，表示热情、温暖而有力。','主人主动照料客人，体现热情真诚。')],mistakes:[M('The hosts gave a hearty welcome by ignoring the hikers, refusing to speak, and closing the door.','The hosts gave no welcome because they ignored the hikers and closed the door.','冷漠拒客与热情欢迎相反。')],quiz:[Q('hearty',1,1,'A hearty welcome is?','warm and enthusiastic','cold and unwilling','a heating device','warm and enthusiastic','hearty 可形容热情真挚的欢迎。'),Q('hearty',2,1,'A hearty laugh sounds?','strong and full','silent and barely audible','like a medical monitor','strong and full','该词可形容强而有力的表达。'),Q('hearty',3,1,'Which greeting is hearty?','“We are delighted you made it—come in and warm up.”','“Go away; we do not want to see you.”','“Your appointment is not today.”','“We are delighted you made it—come in and warm up.”','热情并主动关照体现 hearty。'),Q('hearty',4,1,'A hearty response is usually?','warm, strong, and sincere','cold and cruel','random and disorganized','warm, strong, and sincere','hearty 可形容温暖而有力的态度。')]});
D('heat',{etymology:E('Heat comes from Old English hǣtu, related to hot. It can mean the state of being hot, a cooking source or setting, a qualifying race, or the act of warming something.','heat'),contexts:[C('heat.s3','田径赛事','Only the first two runners in each heat advanced to the final, so the athletes watched the results board as soon as their race ended.','每个预赛小组只有前两名晋级决赛，因此比赛一结束，运动员们就查看成绩板。','Only the first two runners in each heat / advanced to the final / so the athletes watched the results board / as soon as their race ended.','heat 在此指决赛前的一组预赛。','运动员按组竞赛、筛选决赛选手，符合 s3。')],mistakes:[M('Every runner in the heat advanced automatically, although the rules stated that only the first two qualified.','Only the first two runners in the heat advanced under the stated rule.','“每个人都晋级”与规则只取前两名不符。')],quiz:[Q('heat',1,1,'The heat of a summer afternoon is?','the condition of being hot','a group of runners','a cooking appliance','the condition of being hot','s1 指热的状态或性质。'),Q('heat',2,2,'Turn the heat down on the cooker means adjust?','the cooking source or temperature','the race results','the room’s hedge','the cooking source or temperature','s2 指烹饪热源或炉温。'),Q('heat',3,3,'In a tournament, a heat is?','one preliminary race in a series','the final match only','a room heater','one preliminary race in a series','s3 指系列赛事中的一组预赛。'),Q('heat',4,4,'To heat the soup is to?','make it warm','measure its area','make it colder','make it warm','s4 作动词表示加热。')]});
D('heated',{etymology:E('Heated is the past participle of heat. Figuratively, it describes an argument or discussion that has become angry and emotionally intense.','heated'),contexts:[C('heated.s1','公共会议','The budget meeting became heated when residents learned that the only neighborhood clinic might lose its funding.','居民得知社区唯一的诊所可能失去经费后，预算会议变得激烈起来。','The budget meeting became heated / when residents learned / that the only neighborhood clinic / might lose its funding.','heated 描写情绪激动、带有怒气的讨论。','居民因诊所可能停资而强烈争论，符合该义。')],mistakes:[M('The discussion remained heated because everyone stayed calm, agreed immediately, and showed no strong emotion.','The discussion remained calm because everyone agreed without strong emotion.','冷静一致的讨论不是 heated argument。')],quiz:[Q('heated',1,1,'A heated argument is?','angry and emotionally intense','physically frozen','about a cooking device only','angry and emotionally intense','heated 可比喻情绪激烈的争论。'),Q('heated',2,1,'Which exchange is heated?','two speakers angrily interrupting one another','two colleagues quietly agreeing','a calm written thank-you note','two speakers angrily interrupting one another','愤怒插话体现争论激烈。'),Q('heated',3,1,'A heated debate may concern?','a strongly disputed policy','a quiet uncontroversial schedule','the area of a field','a strongly disputed policy','争议强烈的话题容易引发 heated debate。'),Q('heated',4,1,'The adjective heated comes from the verb?','heat','heed','hedge','heat','heated 是 heat 的过去分词形容词。','word-formation')]});
D('heater',{etymology:E('Heater is formed from heat plus the agent or instrument suffix -er. It names a device that warms a room, water, or another object.','heater'),contexts:[C('heater.s1','家庭维修','The plumber replaced the faulty water heater before the family returned, restoring hot water to the kitchen and upstairs bathroom.','家人回来前，管道工更换了故障热水器，恢复了厨房和楼上浴室的热水供应。','The plumber replaced the faulty water heater / before the family returned / restoring hot water / to the kitchen and upstairs bathroom.','heater 指用于加热的设备。','更换设备后恢复热水，体现热水器用途。')],mistakes:[M('The broken heater cooled the water and lowered the room temperature whenever it was switched on.','The working heater warmed the water and raised the room temperature when switched on.','持续冷却而非加热的设备不是 heater。')],quiz:[Q('heater',1,1,'A heater is a device that?','makes something warm','measures a hectare','cools a room','makes something warm','heater 指加热设备。'),Q('heater',2,1,'A water heater supplies?','hot water','a race result','a heartfelt apology','hot water','热水器加热生活用水。'),Q('heater',3,1,'Which item is a heater?','an electric radiator','a garden hedge','a handheld harmonica','an electric radiator','电暖器用于提升室温。'),Q('heater',4,1,'The suffix -er in heater indicates?','a device that performs an action','a place of worship','a feeling of grief','a device that performs an action','-er 可构成器具名称。','word-formation')]});
D('heave',{etymology:E('Heave comes from Old English hebban, “lift.” It can mean lift or throw something heavy, rise and fall repeatedly, feel about to vomit, or an effortful lift or throw.','heave'),contexts:[C('heave.s3','海上航行','The small boat began to heave on the swell, rising and falling as waves passed beneath the hull.','小船开始随着涌浪起伏，海浪从船体下方经过时，船身一上一下。','The small boat began to heave on the swell / rising and falling / as waves passed / beneath the hull.','heave 在此是不及物动词，表示反复上下起伏。','船随波浪不断升降，符合 s3。')],mistakes:[M('The boat heaved steadily on the swell while remaining perfectly motionless at the same level.','The boat stayed motionless on the water without heaving.','保持完全静止与反复起伏相矛盾。')],quiz:[Q('heave',1,1,'To heave a heavy crate is to?','lift or pull it with effort','paint it carefully','measure its temperature','lift or pull it with effort','s1 指费力抬起或拉动。'),Q('heave',2,2,'To heave a stone over a wall is to?','throw it with force','place it gently on the ground','weigh the wall','throw it with force','s2 指用力投掷重物。'),Q('heave',3,3,'A boat heaves on waves when it?','rises and falls repeatedly','stays fixed above the water','becomes a heater','rises and falls repeatedly','s3 描述反复起伏。'),Q('heave',4,4,'If someone begins to heave with nausea, they feel?','as if they may vomit','ready to lift a chair','warm and comfortable','as if they may vomit','s4 指恶心并几乎要呕吐。')]});
D('heaven',{etymology:E('Heaven comes from Old English heofon, from a Germanic word for the sky. It can refer to a religious afterlife, the sky, or a state or place of exceptional pleasure.','heaven'),contexts:[C('heaven.s3','休闲感受','After a long shift, soaking in the quiet hot spring felt like heaven to the exhausted hikers.','长时间值班后，疲惫的徒步者觉得泡在宁静的温泉里简直像天堂一样舒服。','After a long shift / soaking in the quiet hot spring / felt like heaven / to the exhausted hikers.','heaven 在此比喻极其愉快舒适的状态。','温泉带来难得的放松与舒适，符合 s3。')],mistakes:[M('The hikers called the scorching, painful water heaven because it caused them severe discomfort and burns.','The hikers called the soothing hot spring a relief because it eased their discomfort.','造成严重疼痛和灼伤的水不可能令人觉得像天堂般舒适。')],quiz:[Q('heaven',1,1,'In some religions, heaven is?','the place where good people go after death','a cooking appliance','a small village','the place where good people go after death','s1 是宗教中的来世居所。'),Q('heaven',2,2,'A person looking up at the stars may gaze at?','the heavens','a hearth','a hectare','the heavens','s2 指天空，尤其夜空。'),Q('heaven',3,3,'“A quiet beach was heaven” means it was?','extremely pleasant','a religious building','too hot to approach','extremely pleasant','s3 是极其惬意的比喻义。'),Q('heaven',4,1,'Which question asks about the religious sense?','Where do believers say the good go after death?','How warm is the cooker?','Which race heat is next?','Where do believers say the good go after death?','来世归宿对应宗教义。')]});
D('heavenly',{etymology:E('Heavenly is formed from heaven plus -ly. It can mean belonging to heaven or the sky, and informally can praise something as extremely pleasant.','heavenly'),contexts:[C('heavenly.s2','甜点评价','The warm pear tart with cardamom cream tasted heavenly after the group had spent a cold afternoon outdoors.','一群人在户外度过寒冷的下午后，温热的梨挞配豆蔻奶油尝起来美妙极了。','The warm pear tart with cardamom cream / tasted heavenly / after the group / had spent a cold afternoon outdoors.','heavenly 在此作非正式赞美，表示极其美好可口。','寒冷之后享用温热甜点，带来特别愉快的体验。')],mistakes:[M('The diners called the tart heavenly, though it was spoiled, tasted bitter, and made everyone ill.','The diners called the spoiled tart unpleasant because it tasted bitter and made them ill.','变质并令人不适的食物不应被赞为 heavenly。')],quiz:[Q('heavenly',1,1,'A heavenly body is?','an object in the sky','a room heater','a heartfelt apology','an object in the sky','s1 可指天体或天空的。'),Q('heavenly',2,2,'A heavenly dessert tastes?','extremely pleasant','cold and spoiled','like a metal helmet','extremely pleasant','s2 是非正式赞美，表示美味或极佳。'),Q('heavenly',3,1,'Which phrase uses heavenly literally?','heavenly light visible above the horizon','heavenly soup at a restaurant','a heavenly welcome from a host','heavenly light visible above the horizon','天体或天空中的光对应字面义。'),Q('heavenly',4,2,'If a meal is heavenly, the speaker is?','praising it as exceptionally good','saying it is impossible to eat','describing its temperature only','praising it as exceptionally good','该词作非正式赞美。')]});
D('heavens',{etymology:E('Heavens is the plural of heaven. In common expressions and descriptions it can mean the sky or the expanse above the earth, especially at night.','heavens'),contexts:[C('heavens.s1','夜空观测','Far from the city lights, the campers watched the heavens darken and saw the Milky Way stretch above the ridge.','远离城市灯光后，露营者看着夜空渐暗，看到银河横亘在山脊上方。','Far from the city lights / the campers watched the heavens darken / and saw the Milky Way / stretch above the ridge.','heavens 在此指天空、夜空。','观察银河和夜色变化对应天空义。')],mistakes:[M('The campers looked up at the heavens beneath the soil and saw stars underground.','The campers looked up at the heavens above the ridge and saw stars in the night sky.','heavens 指头顶天空，不是地下。')],quiz:[Q('heavens',1,1,'The heavens at night are?','the sky above the earth','the floor by a fireplace','a set of race heats','the sky above the earth','heavens 可指夜空。'),Q('heavens',2,1,'An astronomer observing the heavens studies?','objects in the sky','the interior of a heater','a hectare boundary','objects in the sky','天文学家观察天空中的天体。'),Q('heavens',3,1,'The word heavens is grammatically the plural of?','heaven','heating','hearth','heaven','heavens 是 heaven 的复数形式。','plural'),Q('heavens',4,1,'Which image belongs in the heavens?','stars above a mountain','roots under a garden hedge','tools in a shed','stars above a mountain','星星位于天空中。')]});
D('heavily',{etymology:E('Heavily is formed from heavy plus -ly, with y changing to i. It means with great weight or force.','heavily'),contexts:[C('heavily.s1','仓库运输','The delivery truck was heavily loaded with stone tiles, so the driver took the longer route with a lower bridge gradient.','送货卡车装了大量石砖，因此司机选择坡度较缓的绕行路线。','The delivery truck was heavily loaded with stone tiles / so the driver took the longer route / with a lower bridge gradient.','heavily 修饰 loaded，表示装载了很重的负荷。','石砖数量多、重量大，符合该副词义。')],mistakes:[M('The truck was heavily loaded even though it carried no cargo and its weight was below the empty vehicle’s weight.','The empty truck was not heavily loaded because it carried no cargo.','没有货物的空车不属于重载状态。')],quiz:[Q('heavily',1,1,'A heavily loaded cart carries?','a large weight','almost nothing','a heavenly meal','a large weight','heavily 可表示负荷很重。'),Q('heavily',2,1,'If rain falls heavily, it falls?','with great force or intensity','as a light mist only','once every few years','with great force or intensity','heavily 也可表示猛烈地。'),Q('heavily',3,1,'The suffix -ly in heavily forms?','an adverb','a plural noun','a place name','an adverb','heavy 加 -ly 构成方式副词。','word-formation'),Q('heavily',4,1,'A door hangs heavily when it?','moves or rests with substantial weight','weighs nothing at all','is made of paper','moves or rests with substantial weight','该副词指重量或力量很大。')]});
D('heavy',{etymology:E('Heavy comes from Old English hefig. It describes great weight, a large amount or intensity, sadness, demanding effort or responsibility, and an action done with force.','heavy'),contexts:[C('heavy.s4','职业职责','For a new team leader, managing the emergency roster was a heavy responsibility because every shift affected patient safety.','对新任组长来说，管理应急值班表是沉重的责任，因为每个班次都关系到患者安全。','For a new team leader / managing the emergency roster / was a heavy responsibility / because every shift affected patient safety.','heavy 修饰 responsibility，表示责任重大、负担沉重。','工作影响患者安全，使职责格外重大。')],mistakes:[M('The team leader described the responsibility as heavy, though it involved no decisions, effort, or consequences.','The team leader described the responsibility as light because it involved no decisions or consequences.','没有决策和后果的琐事不构成重大责任。')],quiz:[Q('heavy',1,1,'A heavy suitcase is?','difficult to lift because it weighs a lot','easy to carry because it is empty','a unit of land','difficult to lift because it weighs a lot','s1 指重量大。'),Q('heavy',2,2,'Heavy rain means rain of great?','amount or intensity','sadness','height','amount or intensity','s2 指数量或强度很大。'),Q('heavy',3,3,'A heavy mood may feel?','sad or gloomy','light and cheerful','warm and sincere','sad or gloomy','s3 指悲伤、阴郁。'),Q('heavy',4,4,'A heavy responsibility is?','demanding and serious','physically made of metal only','easy to ignore','demanding and serious','s4 指费力且责任重大。')]});
D('hectare',{etymology:E('Hectare is formed from hecto-, “one hundred,” and are, a metric unit of area equal to 100 square metres. One hectare therefore equals 10,000 square metres.','hectare'),contexts:[C('hectare.s2','林地测量','The forestry team mapped a hectare of young woodland to estimate how many seedlings would survive the coming dry season.','林业队绘制了一公顷幼林的地图，以估算有多少树苗能熬过即将到来的旱季。','The forestry team mapped a hectare of young woodland / to estimate / how many seedlings / would survive the coming dry season.','hectare 在此用于测量林地面积。','幼林地块以公顷为单位测量，符合 s2。')],mistakes:[M('The farm measured a hectare of land as only ten square metres and planted a field across the claimed area.','The farm measured a hectare as 10,000 square metres.','一公顷不是十平方米，而是10,000平方米。')],quiz:[Q('hectare',1,1,'One hectare equals?','10,000 square metres','100 square metres','one square kilometre','10,000 square metres','1 hectare = 10,000 平方米。'),Q('hectare',2,2,'A hectare is often used to measure?','farmland or forest area','a person’s heartbeat','the temperature of a heater','farmland or forest area','公顷常用于土地面积计量。'),Q('hectare',3,1,'How many ares make one hectare?','100','10','1,000','100','hecto- 表示一百，1公顷等于100公亩。','measurement'),Q('hectare',4,1,'Which area is approximately one hectare?','a square plot about 100 metres on each side','a 10-by-10-metre garden','a 1-by-1-metre floor tile','a square plot about 100 metres on each side','100×100米等于10,000平方米。')]});
D('hectic',{etymology:E('Hectic came through Latin hecticus from Greek hektikos, originally associated with a recurring fever. Modern English commonly means extremely busy and full of activity; the fever-related sense remains in medical or literary use.','hectic'),contexts:[C('hectic.s1','工作安排','The clinic had a hectic Monday, with walk-in patients arriving continuously while two staff members covered the reception desk.','诊所周一忙得不可开交，临时就诊的患者不断到来，同时只有两名员工负责接待。','The clinic had a hectic Monday / with walk-in patients arriving continuously / while two staff members / covered the reception desk.','hectic 描写活动繁忙、节奏紧张的一天。','患者不断到来且人手有限，构成忙乱情景。')],mistakes:[M('The clinic had a hectic day because it received no visitors, had no tasks, and closed early.','The clinic had a quiet day because it received no visitors and had few tasks.','没有访客和任务的日子不符合忙碌之义。')],quiz:[Q('hectic',1,1,'A hectic schedule is?','very busy and full of activity','empty and without plans','a large area of land','very busy and full of activity','s1 指繁忙紧张。'),Q('hectic',2,2,'In older or medical use, hectic may be associated with?','fever','a land survey','a musical instrument','fever','s2 与发热有关。'),Q('hectic',3,1,'Which day sounds hectic?','one with back-to-back urgent appointments','one with no visitors or duties','one spent quietly reading at home','one with back-to-back urgent appointments','连续紧急预约使日程很忙。'),Q('hectic',4,1,'A hectic week may leave a worker?','busy and tired','idle and unstimulated','unable to measure land','busy and tired','繁忙的一周容易让人疲惫。')]});
D('hedge',{etymology:E('Hedge comes from Old English hecg, a row of bushes forming a boundary. It also means protection against risk, surrounding something with a hedge, or avoiding a direct answer.','hedge'),contexts:[C('hedge.s4','媒体采访','Asked whether the policy would change, the spokesperson hedged and gave no direct answer, saying only that officials were “reviewing options.”','被问及政策是否会改变时，发言人闪烁其词，没有直接回答，只说官员正在“审查选项”。','Asked whether the policy would change / the spokesperson hedged / and gave no direct answer / saying only that officials were “reviewing options.”','hedged 在此表示避免给出明确答复。','含糊回应、回避是非问题，符合 s4。')],mistakes:[M('The spokesperson hedged by answering the yes-or-no question directly and stating the decision without qualification.','The spokesperson answered directly rather than hedging.','直接明确回答不属于回避表态。')],quiz:[Q('hedge',1,1,'A garden hedge is?','a row of bushes used as a boundary','a measure of land','a heater','a row of bushes used as a boundary','s1 指树篱。'),Q('hedge',2,2,'A financial hedge is intended to?','protect against possible loss or risk','make every investment riskier','hide a garden gate','protect against possible loss or risk','s2 指风险对冲或保护措施。'),Q('hedge',3,3,'To hedge a garden is to?','surround or divide it with a hedge','measure it in hectares','heat it','surround or divide it with a hedge','s3 作动词指用树篱围住或隔开。'),Q('hedge',4,4,'A spokesperson hedges when they?','avoid giving a direct answer','state a clear yes or no','read a handbook aloud','avoid giving a direct answer','s4 指含糊其词、回避明确表态。')]});
D('hedgehog',{etymology:E('Hedgehog combines hedge and hog. The name refers to a small nocturnal mammal that often forages in hedges and has a rounded, piglike snout; when threatened it raises its spines and curls into a ball.','hedgehog'),contexts:[C('hedgehog.s1','夜间观察','The hedgehog curled into a ball when the garden light came on, raising its spines before slowly moving beneath the hedge.','花园灯亮起时，刺猬蜷成一团、竖起刺，然后慢慢钻到树篱下面。','The hedgehog curled into a ball / when the garden light came on / raising its spines / before slowly moving beneath the hedge.','hedgehog 指夜行的小型哺乳动物，受威胁时会蜷缩并竖刺。','行为符合刺猬的防御方式。')],mistakes:[M('The hedgehog defended itself by spreading smooth feathers and flying over the garden fence.','The hedgehog defended itself by raising its spines and curling into a ball.','刺猬没有羽毛或飞行能力，会用棘刺防御。')],quiz:[Q('hedgehog',1,1,'A hedgehog is a small mammal that?','can curl into a ball and raise its spines','has broad wings for flight','lives only in the sea','can curl into a ball and raise its spines','刺猬受威胁时会蜷缩竖刺。'),Q('hedgehog',2,1,'When are hedgehogs often active?','at night','only at midday in open water','during winter flights','at night','hedgehog 是夜行性动物。'),Q('hedgehog',3,1,'A hedgehog’s spines mainly help it?','defend itself','measure a hectare','make a heartbeat','defend itself','棘刺是防御结构。'),Q('hedgehog',4,1,'The word hedgehog contains the element hedge because it often?','forages near hedges','builds a hedge from its spines','lives inside a heater','forages near hedges','其名称与常在树篱附近活动有关。','word-formation')]});
D('heed',{etymology:E('Heed comes from Old English hēdan, “take care or pay attention.” As a verb it means give careful attention to advice, a warning, or a sign.','heed'),contexts:[C('heed.s1','安全提示','Drivers must heed the flashing sign and slow down before entering the bridge, where workers are replacing a damaged barrier.','驾驶员必须注意闪烁的标志，并在驶入桥梁前减速，因为工人正在更换受损护栏。','Drivers must heed the flashing sign / and slow down / before entering the bridge / where workers are replacing a damaged barrier.','heed 是动词，表示认真注意并遵从提示。','司机按警示牌减速，体现留意并采取行动。')],mistakes:[M('The driver heeded the warning sign by ignoring it and accelerating toward the closed bridge.','The driver ignored the warning sign and accelerated toward the closed bridge.','无视警示并加速与 heed 警告相反。')],quiz:[Q('heed',1,1,'To heed a warning is to?','pay attention to it and act accordingly','cover it with paint','forget it immediately','pay attention to it and act accordingly','heed 表示注意并听从。'),Q('heed',2,1,'A careful driver should heed?','a flashing road sign','a random rumor unrelated to travel','a garden hedge','a flashing road sign','驾驶员应注意道路警示。'),Q('heed',3,1,'Which sentence uses heed correctly?','She heeded the doctor’s advice and rested.','She heeded to the doctor’s advice and rested.','She heeded the advice by refusing to hear it.','She heeded the doctor’s advice and rested.','heed 通常直接接宾语，不需 to。','grammar'),Q('heed',4,1,'If workers heed a safety rule, they?','follow it carefully','remove it from the handbook','make it harder to hear','follow it carefully','heed 强调重视并遵守。')]});

D('heedless',{etymology:E('Heedless combines heed, “attention or notice,” with -less, meaning without. It describes failing to pay attention or take care.','heedless'),contexts:[C('heedless.s1','道路安全','A heedless cyclist rode through the temporary barrier without looking, narrowly missing a worker carrying road signs.','一名粗心的骑车人没有看路便穿过临时护栏，险些撞上正在搬路标的工人。','A heedless cyclist rode through the temporary barrier / without looking / narrowly missing / a worker carrying road signs.','heedless 描写没有留意周围情况、疏忽大意。','无视护栏且不观察道路，符合该义。')],mistakes:[M('The heedless driver carefully checked every sign, followed each warning, and gave way to workers.','The attentive driver checked every sign, followed warnings, and gave way to workers.','细心遵守警示不属于 heedless。')],quiz:[Q('heedless',1,1,'A heedless action is done?','without paying attention or taking care','after careful thought','with full awareness of every warning','without paying attention or taking care','heedless 表示不留意、疏忽。'),Q('heedless',2,1,'Which person is heedless near a roadwork site?','someone who ignores barriers and signs','someone who slows down for workers','someone who checks the crossing is clear','someone who ignores barriers and signs','无视施工警示属于疏忽。'),Q('heedless',3,1,'The suffix -less in heedless means?','without','full of','able to give','without','-less 表示缺少或没有。','word-formation'),Q('heedless',4,1,'A heedless mistake often results from?','not noticing an important detail','checking all details twice','following clear instructions','not noticing an important detail','疏忽通常源于没有注意关键细节。')]});
D('heel',{etymology:E('Heel comes from Old English hēla, from a Germanic root. It names the back of the foot, a shoe’s raised support, and several related uses including follow closely, lean to one side, or the end of a loaf.','heel'),contexts:[C('heel.s5','餐桌用语','She saved the heel of the sourdough loaf for soup, cutting off the firm end piece and storing it in a paper bag.','她把酸面包的尾端留着配汤，切下较硬的最后一块并装进纸袋。','She saved the heel of the sourdough loaf for soup / cutting off the firm end piece / and storing it / in a paper bag.','heel 在此指面包末端的一片。','她切下并保存面包尾块，符合 s5。')],mistakes:[M('She saved the heel of the loaf, but described it as the soft middle slice rather than an end piece.','She saved the heel of the loaf, the firm end piece.','面包中间片不叫 heel，heel 是尾端部分。')],quiz:[Q('heel',1,1,'The heel of your foot is?','the rounded back part','the front of the toes','the arch only','the rounded back part','s1 指脚后跟。'),Q('heel',2,2,'The heel of a shoe is?','the raised part beneath the back','the tongue under the laces','the toe cap','the raised part beneath the back','s2 指鞋后跟。'),Q('heel',3,3,'A dog heels when it?','follows closely behind its handler','runs far ahead and disappears','leans over in a boat','follows closely behind its handler','s3 作动词指紧跟在某人身后。'),Q('heel',4,5,'The heel of a loaf is?','an end piece','the centre slice','the paper wrapper','an end piece','s5 指面包尾片。')]});
D('hegemony',{etymology:E('Hegemony comes from Greek hēgemonia, “leadership,” through Latin. It means control or dominating influence, especially one country’s influence over others.','hegemony'),contexts:[C('hegemony.s1','国际关系','The historian described the empire’s regional hegemony as political and economic dominance maintained through alliances, trade, and military power.','历史学家把该帝国的地区霸权描述为通过联盟、贸易和军事实力维持的政治与经济支配。','The historian described the empire’s regional hegemony / as political and economic dominance / maintained through alliances, trade, / and military power.','hegemony 指一方对其他国家或群体的主导控制力。','通过多种力量维持地区支配，符合该定义。')],mistakes:[M('The historian called the equal partnership hegemony even though no country dominated or controlled another.','The historian called it a cooperative partnership because no country dominated another.','没有支配关系的平等合作不构成 hegemony。')],quiz:[Q('hegemony',1,1,'A country’s hegemony over a region means?','its dominating influence there','its complete lack of influence','a small agricultural area','its dominating influence there','hegemony 指主导性影响或控制。'),Q('hegemony',2,1,'Which situation suggests hegemony?','one state sets regional rules through superior power','several states share decisions as equals','a village elects a local council','one state sets regional rules through superior power','一方凭借优势设定规则体现支配地位。'),Q('hegemony',3,1,'The word is most often used in?','political and historical discussion','recipe instructions','shoe repair','political and historical discussion','该词多用于政治、历史语境。'),Q('hegemony',4,1,'The Greek source hēgemonia meant?','leadership','heat','a loaf end','leadership','词源与领导、主导相关。','word-formation')]});
D('height',{etymology:E('Height is formed from high with an older noun suffix and comes from Old English hīehþ. It can mean vertical measurement, a high place or position, or the most intense point of something.','height'),contexts:[C('height.s3','旅游季节','At the height of the summer festival, the old town’s narrow streets were filled with music, food stalls, and visitors.','夏季节庆最热闹的时候，老城区狭窄的街道上挤满了音乐、食品摊和游客。','At the height of the summer festival / the old town’s narrow streets / were filled / with music, food stalls, and visitors.','at the height of 表示达到某事物最强、最兴盛的阶段。','街区在节庆高峰期最为繁忙，符合 s3。')],mistakes:[M('At the height of the festival, the town was completely empty and the event had not yet begun.','Before the festival began, the town was empty.','无人且尚未开始不是活动达到最兴盛的时刻。')],quiz:[Q('height',1,1,'The height of a tower is measured from?','its bottom to its top','one side to the other','the ground to the sea floor only','its bottom to its top','s1 指底部到顶部的距离。'),Q('height',2,2,'A climber reached a great height when reaching?','a high place','the lowest point of a valley','the end of a loaf','a high place','s2 指高处或高位。'),Q('height',3,3,'At the height of a crisis means?','at its most intense point','before it starts','after it has vanished','at its most intense point','s3 指最高潮或最强阶段。'),Q('height',4,1,'Which question asks for physical height?','How tall is the flagpole?','How intense was the debate?','When did the festival peak?','How tall is the flagpole?','询问旗杆多高对应尺寸义。')]});
D('heighten',{etymology:E('Heighten is formed from height plus -en, a verb-forming suffix. It means make something higher, stronger, or more intense.','heighten'),contexts:[C('heighten.s1','安全警戒','The unexplained vibration heightened concern among the engineers, who paused the test until they could inspect the motor mount.','无法解释的振动加剧了工程师们的担忧，他们暂停测试，直到检查完电机支架。','The unexplained vibration heightened concern / among the engineers / who paused the test / until they could inspect the motor mount.','heightened 在此表示使担忧增强。','振动令工程师更担心，并导致停测，符合词义。')],mistakes:[M('The unexplained vibration heightened concern by making every engineer less worried than before.','The unexplained vibration eased concern by making the engineers less worried.','担忧减少是 ease，而不是 heighten。')],quiz:[Q('heighten',1,1,'To heighten concern is to?','make it stronger','remove it completely','measure it in hectares','make it stronger','heighten 表示增强。'),Q('heighten',2,1,'A sudden alarm can heighten?','people’s awareness of danger','the weight of a handbook','the length of a loaf','people’s awareness of danger','警报会增强人们对危险的警觉。'),Q('heighten',3,1,'Which action may heighten suspense in a story?','delaying the reveal while danger approaches','explaining the ending immediately','removing every unanswered question','delaying the reveal while danger approaches','延迟揭晓并加大危险会加强悬念。'),Q('heighten',4,1,'The suffix -en in heighten helps form a verb meaning?','make higher or stronger','make less visible','name a person','make higher or stronger','-en 构成“使……变得”的动词。','word-formation')]});
D('heir',{etymology:E('Heir came through Old French heir from Latin hērēs, “heir.” It means a person legally entitled to inherit property, or someone who continues another person’s work or tradition.','heir'),contexts:[C('heir.s2','家族事业','After the founder retired, her granddaughter became the heir to the family bakery’s recipes and responsibility for training the next generation.','创始人退休后，她的孙女成为家族面包店技艺的继承者，并负责培养下一代。','After the founder retired / her granddaughter became the heir / to the family bakery’s recipes / and responsibility for training the next generation.','heir 在此比喻继承前人事业与传统的人。','孙女延续配方与技艺，符合 s2。')],mistakes:[M('The granddaughter was called heir to the family tradition, although she rejected it and had no intention of continuing the work.','The granddaughter declined to become heir to the family tradition because she would not continue the work.','拒绝继续传统与成为其继承者相矛盾。')],quiz:[Q('heir',1,1,'A legal heir may receive?','property after someone’s death','a race heat before the final','a fireplace floor','property after someone’s death','s1 指依法继承财产的人。'),Q('heir',2,2,'An heir to a musical tradition is someone who?','continues its work or style','inherits a house by law only','measures its sound','continues its work or style','s2 指延续传统的人。'),Q('heir',3,1,'A will may name an heir to?','inherit an estate','operate a heater','join a hedge','inherit an estate','遗嘱指定财产继承人。'),Q('heir',4,2,'A young scientist called heir to a mentor’s work is expected to?','carry the research forward','inherit a loaf’s heel','run a preliminary race','carry the research forward','比喻义是接续前人的工作。')]});
D('heirship',{etymology:E('Heirship combines heir with -ship. It means the legal right to inherit property or the state or position of being an heir.','heirship'),contexts:[C('heirship.s1','遗产法律','The court reviewed the will and the adoption documents before deciding the child’s heirship and right to receive the estate.','法院在裁定孩子的继承权和接受遗产的权利前，审查了遗嘱和收养文件。','The court reviewed the will and the adoption documents / before deciding the child’s heirship / and right to receive / the estate.','heirship 在此指依法继承财产的权利。','法院依据法律文件判定遗产继承权。')],mistakes:[M('The court confirmed her heirship but ruled that she had no legal right to inherit any property.','The court confirmed her heirship and legal right to inherit property.','确认继承资格却完全否认继承权相互矛盾。')],quiz:[Q('heirship',1,1,'Heirship may refer to?','the legal right to inherit property','a high mountain peak','a warm greeting','the legal right to inherit property','s1 指继承财产的法律权利。'),Q('heirship',2,2,'The state of being an heir is called?','heirship','hegemony','helical motion','heirship','s2 指继承人的身份或地位。'),Q('heirship',3,1,'A court might examine a will to settle?','a person’s heirship','a helicopter’s route','the height of a tree','a person’s heirship','遗嘱用于确认继承身份和权利。'),Q('heirship',4,1,'The suffix -ship in heirship forms a noun for?','a status or condition','a place of punishment','a cooking temperature','a status or condition','-ship 可表示身份或状态。','word-formation')]});
D('heliacal',{etymology:E('Heliacal comes from Greek hēliakos, “of the sun,” from hēlios “sun.” In astronomy it describes a star’s rising shortly before sunrise or setting shortly after sunset.','heliacal'),contexts:[C('heliacal.s1','天文观测','The astronomer recorded the heliacal rising of Sirius when the star first became visible above the eastern horizon just before dawn.','天文学家记录了天狼星的偕日升，即这颗星在黎明前首次出现在东方地平线上。','The astronomer recorded the heliacal rising of Sirius / when the star first became visible / above the eastern horizon / just before dawn.','heliacal 修饰 rising，指恒星在太阳升起前短暂可见的偕日现象。','黎明前东方初现的恒星符合偕日升。')],mistakes:[M('The heliacal rising of the star was observed at noon, many hours after the Sun had already crossed the sky.','The star’s heliacal rising was observed shortly before sunrise.','偕日升发生在日出前后，不是正午。')],quiz:[Q('heliacal',1,1,'A heliacal rising occurs when a star becomes visible?','shortly before sunrise','at noon in full daylight','only after midnight underground','shortly before sunrise','heliacal 与太阳升起前后相关。'),Q('heliacal',2,1,'The Greek root helios means?','sun','moon','starfish','sun','heliacal 源自表示太阳的词根。','word-formation'),Q('heliacal',3,1,'An astronomer studying a heliacal setting watches a star?','disappear shortly after sunset','rise at midday','move below the horizon at noon','disappear shortly after sunset','偕日落指恒星日落后不久西沉。'),Q('heliacal',4,1,'Which observation is heliacal?','a star first seen just before dawn after its absence','a star seen overhead at midnight','a planet measured in hectares','a star first seen just before dawn after its absence','黎明前重现符合 heliacal 现象。')]});
D('helical',{etymology:E('Helical is formed from helix plus -al, ultimately from Greek helix “spiral.” It describes a shape that winds around an axis like a screw.','helical'),contexts:[C('helical.s1','机械设计','The spring has a helical coil that wraps evenly around its central axis, allowing it to compress and expand under load.','弹簧由螺旋线圈构成，线圈均匀绕着中心轴，使其能在负载下压缩和伸展。','The spring has a helical coil / that wraps evenly / around its central axis / allowing it to compress and expand under load.','helical 描写螺旋状、绕轴盘旋的形状。','线圈绕中心轴卷绕，符合词义。')],mistakes:[M('The shaft had a helical groove running as a perfectly straight line with no turn around its axis.','The shaft had a straight groove rather than a helical one.','不绕轴旋转的直槽不是 helical。')],quiz:[Q('helical',1,1,'A helical structure is shaped like?','a screw or spiral around an axis','a flat square sheet','a straight line with no curve','a screw or spiral around an axis','helical 指螺旋状。'),Q('helical',2,1,'Which object has a helical form?','a coiled spring','a flat ruler','a cube with no grooves','a coiled spring','弹簧线圈呈螺旋形。'),Q('helical',3,1,'The root helix means?','spiral','height','heat','spiral','helix 指螺旋曲线。','word-formation'),Q('helical',4,1,'A helical groove winds?','around a central axis','only across a flat surface','through a loaf of bread','around a central axis','螺旋槽绕轴延伸。')]});
D('helicopter',{etymology:E('Helicopter was coined in French from Greek helix, “spiral,” and pteron, “wing.” It names a rotor-powered aircraft and can also mean transport or travel by helicopter.','helicopter'),contexts:[C('helicopter.s2','山地救援','Rescuers helicoptered the injured climber from the ridge to a hospital landing pad before the storm reached the valley.','救援人员在风暴抵达山谷前，用直升机把受伤的登山者从山脊送到医院停机坪。','Rescuers helicoptered the injured climber / from the ridge / to a hospital landing pad / before the storm reached the valley.','helicopter 在此作动词，表示用直升机运送。','伤员搭乘直升机从山脊转运至医院。')],mistakes:[M('The rescue team helicoptered the climber by carrying him on foot along the ridge with no aircraft.','The rescue team carried the climber by helicopter from the ridge to the hospital.','徒步搬运不属于用直升机转运。')],quiz:[Q('helicopter',1,1,'A helicopter flies using?','large rotating blades','fixed sails','a hand-cranked wheel','large rotating blades','s1 指旋翼驱动的航空器。'),Q('helicopter',2,2,'To helicopter a patient means?','transport the patient by helicopter','treat the patient’s hearing','make the patient a legal heir','transport the patient by helicopter','s2 可作动词表示直升机运送。'),Q('helicopter',3,1,'Which aircraft can hover by using rotors?','a helicopter','a glider with no engine','a paper kite','a helicopter','直升机的旋翼使其能够悬停。'),Q('helicopter',4,1,'The coined word combines Greek ideas of?','spiral and wing','heart and beat','height and land','spiral and wing','其构词来源描述旋翼与机翼。','word-formation')]});
D('helium',{etymology:E('Helium is named from Greek hēlios, “sun,” because it was first identified in the Sun’s spectrum before it was found on Earth. It is a colourless, odourless noble gas, lighter than air.','helium'),contexts:[C('helium.s1','气球实验','The science class filled a small weather balloon with helium and tied it securely before releasing it in the school field.','科学课上，学生们给小型气象气球充入氦气，并在学校操场放飞前将它系牢。','The science class filled a small weather balloon with helium / and tied it securely / before releasing it / in the school field.','helium 是比空气轻的无色无味惰性气体。','氦气可使气球升空，符合其物理性质。')],mistakes:[M('The balloon sank because it was filled with helium, a gas much heavier than air.','The balloon rose because it was filled with helium, a gas lighter than air.','氦气比空气轻，充入气球通常使其上升。')],quiz:[Q('helium',1,1,'Helium is a?','colourless noble gas','liquid metal','type of plant','colourless noble gas','helium 是无色惰性气体。'),Q('helium',2,1,'A helium balloon rises because helium is?','lighter than air','heavier than steel','a solid at room temperature','lighter than air','氦气比空气轻。'),Q('helium',3,1,'The name helium is connected to the Greek word for?','the Sun','the Moon','the sea','the Sun','helium 因先在太阳光谱中发现而得名。','word-formation'),Q('helium',4,1,'Helium is used in some applications as?','a coolant','a plant herbicide','a shoe heel','a coolant','氦气也可用于冷却用途。')]});
D('helix',{etymology:E('Helix comes from Greek helix, “spiral” or “whorl,” through Latin. It names a screw-like curve or spiral, including a structure that winds around an axis.','helix'),contexts:[C('helix.s1','生物结构','The textbook diagram showed DNA as a double helix, with two strands winding around one another like a twisted ladder.','教材图示把DNA画成双螺旋，两条链像扭转的梯子一样彼此缠绕。','The textbook diagram showed DNA as a double helix / with two strands / winding around one another / like a twisted ladder.','helix 指螺旋曲线或螺旋结构。','两条链相互盘绕形成双螺旋。')],mistakes:[M('The diagram labeled two parallel straight strands with no twist or coil as a double helix.','The diagram labeled two intertwined spiral strands as a double helix.','没有扭转或盘绕的平行直线不构成双螺旋。')],quiz:[Q('helix',1,1,'A helix is a?','spiral or screw-like curve','flat square','straight line without a turn','spiral or screw-like curve','helix 指螺旋曲线。'),Q('helix',2,1,'DNA is commonly described as a?','double helix','double hectare','double hearth','double helix','DNA 的结构常称双螺旋。'),Q('helix',3,1,'A helix winds around?','an axis','a flat page with no curve','a loaf’s end','an axis','螺旋围绕中心轴延伸。'),Q('helix',4,1,'The Greek source helix is associated with?','a spiral or whorl','a fever','a legal inheritance','a spiral or whorl','词源意为螺旋或卷曲。','word-formation')]});
D('hell',{etymology:E('Hell comes from Old English hel, from a Germanic root. It can name a place of punishment after death in some religions, a very unpleasant situation, or an exclamation expressing anger or emphasis.','hell'),contexts:[C('hell.s2','旅行遭遇','After the ferry was cancelled, the stranded passengers described the freezing terminal with no food or updates as hell.','渡船取消后，被困乘客把那个没有食物也没有消息、冷得刺骨的候船厅称作活受罪。','After the ferry was cancelled / the stranded passengers described / the freezing terminal with no food or updates / as hell.','hell 在此比喻极其糟糕、难以忍受的处境。','寒冷、饥饿且信息缺失的经历符合 s2。')],mistakes:[M('The passengers called the warm, comfortable lounge hell even though every need was met and they enjoyed the stay.','The passengers called the warm, comfortable lounge pleasant because their needs were met.','舒适愉快的环境不符合糟糕处境之义。')],quiz:[Q('hell',1,1,'In some religions, hell is?','a place of punishment after death','a high place above a valley','a device that warms a room','a place of punishment after death','s1 是某些宗教中的死后惩罚之地。'),Q('hell',2,2,'“That delay was hell” means it was?','extremely unpleasant','a pleasant holiday','a legal inheritance','extremely unpleasant','s2 是糟糕难受处境的比喻。'),Q('hell',3,3,'In “Hell, that was close!” the word can express?','anger or emphasis','a precise measurement','a quiet greeting','anger or emphasis','s3 可作感叹语表达情绪或加强语气。'),Q('hell',4,2,'Which situation might someone describe as hell?','hours stranded in freezing weather without help','a relaxing day at a warm spa','a successful family reunion','hours stranded in freezing weather without help','长期受困于恶劣环境会被比喻为 hell。')]});
D('hello',{etymology:E('Hello developed from earlier attention-getting forms such as hallo and hullo; its exact route is uncertain. It is used as a greeting, to answer a telephone, or as the act of greeting someone.','hello'),contexts:[C('hello.s2','电话沟通','“Hello?” Mara said when she answered the landline, then asked the caller to repeat the appointment time.','玛拉接起座机时说了声“喂？”，随后请来电者重复预约时间。','“Hello?” Mara said / when she answered the landline / then asked the caller / to repeat the appointment time.','hello 在此是接听电话时使用的招呼语。','接起电话后先说 hello，符合 s2。')],mistakes:[M('He answered the ringing phone with goodbye before hearing who was calling, then stayed on the line to begin the conversation.','He answered the ringing phone with hello before beginning the conversation.','尚未交谈就用 goodbye 告别，与接电话的 hello 不符。')],quiz:[Q('hello',1,1,'When meeting someone, hello is used to?','greet them','end the conversation','measure their height','greet them','s1 是见面或开场问候。'),Q('hello',2,2,'A caller may say hello when?','answering a telephone','hanging a coat','heating soup','answering a telephone','s2 指接电话时的应答语。'),Q('hello',3,3,'A hello can be?','an act of greeting someone','a small village','a protective helmet','an act of greeting someone','s3 可指一次问候行为。'),Q('hello',4,1,'Which is a natural greeting on arrival?','Hello, it is good to see you.','Hello, I am leaving now; goodbye forever.','Hello, please hand in the keys.','Hello, it is good to see you.','初次见面时 hello 是合适问候。')]});
D('helm',{etymology:E('Helm comes from Old English helm, a steering device or handle, and is related to words for protection. In this entry it names the wheel used to steer a ship.','helm'),contexts:[C('helm.s1','船只操纵','The captain took the helm as the channel narrowed, turning the wheel a few degrees to keep the vessel clear of the rocky shore.','航道变窄时，船长掌舵，轻轻转动舵轮几度，让船只避开多岩石的岸边。','The captain took the helm / as the channel narrowed / turning the wheel a few degrees / to keep the vessel clear of the rocky shore.','helm 指操纵船只方向的舵轮。','船长转动轮盘控制船的航向。')],mistakes:[M('The captain took the helm by switching off the ship’s steering wheel and refusing to guide the vessel.','The captain took the helm and steered the vessel around the rocky shore.','放弃操舵不是掌舵。')],quiz:[Q('helm',1,1,'A ship’s helm is the?','wheel used to steer it','helmet worn by a passenger','heating device in a cabin','wheel used to steer it','helm 指船舵或操舵轮。'),Q('helm',2,1,'A captain at the helm is?','steering the ship','measuring its height','writing its handbook','steering the ship','at the helm 表示掌舵。'),Q('helm',3,1,'The helm helps a vessel change?','direction','temperature','land area','direction','舵轮用来控制方向。'),Q('helm',4,1,'Which phrase uses helm correctly?','The pilot kept a steady hand on the helm.','The cook placed soup in the helm.','The gardener measured a helm of land.','The pilot kept a steady hand on the helm.','掌舵者握住舵轮是自然搭配。')]});
D('helmet',{etymology:E('Helmet came through French and Middle English from a diminutive form related to helm. It names a hard protective covering for the head and can also refer to a protective mask or covering.','helmet'),contexts:[C('helmet.s2','运动防护','The fencer lowered the helmet’s mesh mask before practice so that the face and eyes were protected from a stray blade.','击剑运动员在练习前放下头盔上的网状面罩，以保护脸部和眼睛免受偏离的剑刃伤害。','The fencer lowered the helmet’s mesh mask / before practice / so that the face and eyes / were protected from a stray blade.','helmet 在此指带面罩的防护覆盖物。','网状面罩保护脸和眼睛，符合 s2。')],mistakes:[M('The fencer removed the protective helmet mask so the face would be safer from a stray blade.','The fencer kept the protective helmet mask on to shield the face from a stray blade.','移除防护面罩会降低保护，不会更安全。')],quiz:[Q('helmet',1,1,'A helmet usually protects the?','head','ankles','voice','head','s1 指保护头部的硬质覆盖物。'),Q('helmet',2,2,'A fencer’s helmet may include?','a protective mask','a cooking thermometer','a heel','a protective mask','s2 可指保护面部的面罩。'),Q('helmet',3,1,'A construction worker wears a helmet to reduce?','head injury risk','land measurement errors','heartbreak','head injury risk','安全头盔可降低头部受伤风险。'),Q('helmet',4,1,'Which activity commonly requires a helmet?','cycling on a busy road','answering a phone','reading a handbook','cycling on a busy road','骑车时头盔能保护头部。')]});
D('help',{etymology:E('Help comes from Old English helpan, from a Germanic root. It can mean make a task easier, improve a situation, prevent something, the act of assistance, or a person or thing that assists.','help'),contexts:[C('help.s3','意外防范','The early warning system helped prevent further damage by alerting residents before the river reached the lowest streets.','预警系统在河水涨到最低处街道前提醒居民，帮助防止了进一步损失。','The early warning system helped prevent further damage / by alerting residents / before the river reached / the lowest streets.','help 在此与 prevent 连用，表示有助于避免某事。','及时提醒居民减少了进一步损害，符合 s3。')],mistakes:[M('The warning system helped prevent damage by failing to alert anyone until the river had flooded every street.','The warning system failed to help prevent damage because its alert came too late.','警报迟到且损失已发生，不符合帮助预防的结果。')],quiz:[Q('help',1,1,'To help a neighbour move is to?','make the task easier for them','make the move more difficult','measure their height','make the task easier for them','s1 指协助某人完成事情。'),Q('help',2,2,'A medicine may help a patient by?','improving the condition','making symptoms worse','adding a new injury','improving the condition','s2 指改善状况。'),Q('help',3,3,'A guardrail can help prevent?','a vehicle from leaving the road','a person from saying hello','a heater from warming a room','a vehicle from leaving the road','s3 表示帮助避免事故。'),Q('help',4,5,'A reliable map is a great help because it is?','a thing that assists travellers','a source of heartbreak','a cooking heat','a thing that assists travellers','s5 可指有帮助的人或物。')]});
D('helper',{etymology:E('Helper is formed from help plus the agent suffix -er. It means a person who gives assistance.','helper'),contexts:[C('helper.s1','社区活动','A volunteer helper guided older residents to the registration desk and carried their folded chairs into the meeting room.','一名志愿助手引导年长居民前往登记台，并把折叠椅搬进会议室。','A volunteer helper guided older residents / to the registration desk / and carried their folded chairs / into the meeting room.','helper 指提供协助的人。','引导和搬运都属于协助工作。')],mistakes:[M('The event had no helper because one volunteer guided visitors and carried equipment throughout the day.','The event had a helper who guided visitors and carried equipment.','实际提供帮助的志愿者就是 helper。')],quiz:[Q('helper',1,1,'A helper is someone who?','assists another person','needs a heater','rules a country','assists another person','helper 指帮手、助手。'),Q('helper',2,1,'A classroom helper may?','hand out materials to students','measure the sky','repair a hedge by eating it','hand out materials to students','分发材料是课堂助手的工作。'),Q('helper',3,1,'Which phrase is natural?','a volunteer helper at the event','a hectare helper of rainfall','a heartbeat helper of bread','a volunteer helper at the event','helper 常描述提供协助的人。'),Q('helper',4,1,'The suffix -er in helper refers to?','a person who helps','a place where people meet','a unit of area','a person who helps','-er 构成行为者名词。','word-formation')]});
D('helpful',{etymology:E('Helpful is formed from help plus -ful. It describes something or someone that gives assistance or makes a task easier.','helpful'),contexts:[C('helpful.s1','顾客服务','The station agent gave helpful directions to the family, pointing out the lift and the quieter route to platform six.','车站工作人员给这家人提供了有用的指引，指出电梯和通往六号站台较安静的路线。','The station agent gave helpful directions / to the family / pointing out the lift / and the quieter route to platform six.','helpful 修饰 directions，表示能提供帮助、使事情更容易。','指路帮助乘客找到电梯和站台。')],mistakes:[M('The directions were helpful because they sent the family to a closed exit and concealed the location of every platform.','The directions were unhelpful because they sent the family to a closed exit.','把人引向关闭出口的指引没有帮助。')],quiz:[Q('helpful',1,1,'Helpful advice is advice that?','makes a situation easier to manage','creates extra confusion','is unrelated to the problem','makes a situation easier to manage','helpful 表示有帮助的。'),Q('helpful',2,1,'Which sign is most helpful to a traveller?','a clear arrow to the correct platform','an unreadable notice with no directions','a blank wall','a clear arrow to the correct platform','清晰指向站台的标志能帮助旅客。'),Q('helpful',3,1,'A helpful colleague might?','explain how to use unfamiliar equipment','hide the instructions','interrupt every attempt','explain how to use unfamiliar equipment','提供说明会使任务更容易。'),Q('helpful',4,1,'The suffix -ful in helpful means?','full of or providing','without','past time','full of or providing','-ful 表示具有或提供某种性质。','word-formation')]});
D('helping',{etymology:E('Helping is formed from help plus -ing and is used as a count noun for a portion of food served to someone.','helping'),contexts:[C('helping.s1','家庭晚餐','Grandpa asked for a second helping of vegetable stew after finishing the first bowl, then passed the bread to the children.','爷爷吃完第一碗后又要了一份蔬菜炖菜，然后把面包递给孩子们。','Grandpa asked for a second helping of vegetable stew / after finishing the first bowl / then passed the bread / to the children.','a helping 指一份端给某人食用的食物。','第二碗炖菜是额外的一份。')],mistakes:[M('She asked for another helping of soup, but the server brought a ruler because helping means a unit of length.','She asked for another serving of soup because a helping is a portion of food.','helping 在此是食物份额，不是长度单位。')],quiz:[Q('helping',1,1,'A helping of soup is?','one portion served to a person','a person who assists','a protective helmet','one portion served to a person','helping 可数名词指一份食物。'),Q('helping',2,1,'If someone asks for a second helping, they want?','another portion','a second helper','a second greeting','another portion','second helping 是再添一份。'),Q('helping',3,1,'Which phrase is natural at dinner?','a generous helping of rice','a helping of one hectare','a helping of hello','a generous helping of rice','a helping of rice 表示一份米饭。'),Q('helping',4,1,'At a meal, helping is closest to?','serving','assistance with a task','a sound in a telephone','serving','该名词与一份餐食有关。')]});

D('helpless',{etymology:E('Helpless combines help with -less, meaning without help or power. It describes lacking the strength or means to care for oneself or stop something.','helpless'),contexts:[C('helpless.s1','暴雨应急','With the road washed out and phone service down, the isolated family felt helpless until a rescue team reached the valley.','道路被冲毁、电话服务也中断时，这户与外界隔绝的家庭感到无助，直到救援队抵达山谷。','With the road washed out and phone service down / the isolated family felt helpless / until a rescue team / reached the valley.','helpless 描写缺少自助能力或阻止困境的办法。','道路与通信同时中断，家庭无法自行脱困。')],mistakes:[M('The family felt helpless because they had several safe roads, working phones, and enough help to leave at once.','The family felt secure because roads and phones were working and help was available.','具备道路、通信和支援时并非无助。')],quiz:[Q('helpless',1,1,'A helpless person lacks?','the strength or means to manage alone','any need for support','a phone number','the strength or means to manage alone','helpless 指缺少自助或自我保护能力。'),Q('helpless',2,1,'A stranded family may feel helpless when?','roads and communication are both cut off','rescue teams have already arrived','they have several safe routes','roads and communication are both cut off','无法自行离开时容易感到无助。'),Q('helpless',3,1,'Which response shows someone is not helpless?','they can safely solve the problem with available resources','they have no way to protect themselves','they cannot contact anyone or leave','they can safely solve the problem with available resources','具备能力和资源可摆脱无助状态。'),Q('helpless',4,1,'The suffix -less in helpless means?','without','full of','able to repair','without','-less 表示缺少帮助或能力。','word-formation')]});
D('helplessly',{etymology:E('Helplessly is formed from helpless plus -ly. It means without the power to change or control what is happening.','helplessly'),contexts:[C('helplessly.s1','突发停电','The passengers watched helplessly as the elevator stopped between floors and the emergency lights flickered out.','电梯停在两层楼之间、应急灯也闪灭时，乘客们只能无助地看着。','The passengers watched helplessly / as the elevator stopped between floors / and the emergency lights / flickered out.','helplessly 修饰 watched，表示没有办法改变当时的情况。','乘客无法控制电梯或灯光，只能旁观。')],mistakes:[M('The passengers watched helplessly while operating the elevator controls successfully and opening the doors themselves.','The passengers watched with relief as trained staff operated the controls and opened the doors.','成功操作控制装置就不是无能为力地旁观。')],quiz:[Q('helplessly',1,1,'To watch helplessly is to watch?','without the power to change what happens','while controlling every event','with a clear rescue plan','without the power to change what happens','helplessly 指无力改变局面地。'),Q('helplessly',2,1,'A child may look helplessly at a broken toy when?','they do not know how to repair it','they have already fixed it','they are giving repair instructions','they do not know how to repair it','缺少修理能力时只能无助地看着。'),Q('helplessly',3,1,'Which sentence uses the adverb naturally?','She watched helplessly as the boat drifted away.','She helplessly fixed the leak with the right tools.','The helplessly was near the gate.','She watched helplessly as the boat drifted away.','副词修饰 watched，说明观看时无能为力。','grammar'),Q('helplessly',4,1,'Helplessly describes a manner marked by?','lack of control or power','great confidence','careful planning','lack of control or power','该副词表达无力改变状况。')]});
D('helplessness',{etymology:E('Helplessness is formed from helpless plus -ness. It names the condition of having no power to act, protect oneself, or change a situation.','helplessness'),contexts:[C('helplessness.s1','灾后支援','Access to a working phone and a local relief center reduced the residents’ helplessness after the storm damaged their homes.','风暴损坏房屋后，居民能使用电话并前往本地救助中心，这减轻了他们的无助感。','Access to a working phone and a local relief center / reduced the residents’ helplessness / after the storm / damaged their homes.','helplessness 是缺少行动或自我保护能力的状态。','获得通信和救援资源帮助居民恢复行动能力。')],mistakes:[M('The residents’ helplessness increased because they had full supplies, reliable help, and complete control over repairs.','The residents felt capable of acting because supplies, help, and repair options were available.','资源充足且有控制力与无助状态不符。')],quiz:[Q('helplessness',1,1,'Helplessness is the condition of?','having little power to act or protect oneself','being able to solve every problem','feeling only physical heat','having little power to act or protect oneself','helplessness 指无能为力的状态。'),Q('helplessness',2,1,'Which may reduce a person’s helplessness after a crisis?','clear information and practical support','withholding all assistance','blocking every safe route','clear information and practical support','信息和援助能帮助人重新采取行动。'),Q('helplessness',3,1,'The suffix -ness turns helpless into a noun for?','a condition or state','a person who helps','an action in the past','a condition or state','-ness 构成状态名词。','word-formation'),Q('helplessness',4,1,'A character’s helplessness is strongest when they?','cannot act or protect themselves','have several safe options','can change the outcome easily','cannot act or protect themselves','无助源于缺少行动与保护能力。')]});
D('helpline',{etymology:E('Helpline combines help and line, a telephone line set up for callers seeking information, advice, or support.','helpline'),contexts:[C('helpline.s1','客户支持','The utility’s helpline stayed open through the storm so residents could report outages and ask when power might return.','暴风雨期间，公用事业公司的热线持续开放，居民可以报告停电并询问何时可能恢复供电。','The utility’s helpline stayed open through the storm / so residents could report outages / and ask / when power might return.','helpline 指人们拨打以获取信息或支持的电话号码。','居民拨热线报告故障并获取信息，符合词义。')],mistakes:[M('The helpline refused every call and provided no information, but the notice described it as a working support service.','The phone line was not a functioning helpline because it refused calls and offered no support.','不接听且不提供信息的电话不是有效的支持热线。')],quiz:[Q('helpline',1,1,'A helpline is a phone number people can call for?','information or support','a race result','a unit of land','information or support','helpline 指求助或咨询电话。'),Q('helpline',2,1,'A travel helpline may help callers?','find information about delays','measure a hedge','operate a ship’s helm','find information about delays','热线可提供旅行延误信息。'),Q('helpline',3,1,'Which service is a helpline?','a staffed number for confidential support','a printed handbook with no phone contact','a silent alarm with no response','a staffed number for confidential support','有人接听并提供支持符合热线定义。'),Q('helpline',4,1,'The compound helpline combines help with?','a telephone line','a protective helmet','a land measure','a telephone line','该词指提供帮助的电话线路。','word-formation')]});
D('hem',{etymology:E('Hem comes from Old English hemm, a border or edge. As a noun it is the sewn edge of cloth; as a verb it means sew that edge or surround someone so escape is difficult.','hem'),contexts:[C('hem.s2','服装修补','After shortening the trousers, the tailor hemmed the lower edge with small even stitches so the fabric would not fray.','裁缝把裤子改短后，用均匀的小针脚缝好裤脚边，以免布料散开。','After shortening the trousers / the tailor hemmed the lower edge / with small even stitches / so the fabric would not fray.','hemmed 在此作动词，表示缝折布边。','裤脚边被针线收边，符合 s2 的缝边义。')],mistakes:[M('The tailor hemmed the trousers by cutting away the edge and leaving the fabric raw and unravelled.','The tailor finished the trousers by hemming the folded edge with stitches.','留下散边而未缝折布边，不是 hem。')],quiz:[Q('hem',1,1,'The hem of a skirt is?','its folded and sewn cloth border','the middle of the waistband','a pocket button','its folded and sewn cloth border','s1 指缝好的衣物下摆或边缘。'),Q('hem',2,2,'To hem trousers is to?','sew the folded lower edge','cut a hole in the knee','surround a person in a crowd','sew the folded lower edge','s2 指缝合布料边缘。'),Q('hem',3,2,'To hem someone in is to?','surround them so escape is difficult','sew their coat neatly','measure their height','surround them so escape is difficult','动词还可比喻围住某人。'),Q('hem',4,1,'Why is a cloth edge hemmed?','to finish and secure it','to turn it into a heater','to make it a land boundary','to finish and secure it','缝边可防止布料脱散。')]});
D('hemisphere',{etymology:E('Hemisphere combines hemi-, from Greek hēmi- “half,” with sphere, from Greek sphaira “ball.” It can mean half the Earth, either half of the brain, or a broad half or region of activity.','hemisphere'),contexts:[C('hemisphere.s2','脑部影像','The scan showed a small difference between the brain’s left hemisphere and right hemisphere, so the neurologist requested a follow-up image.','扫描显示大脑左半球与右半球之间有一处细小差异，因此神经科医生要求复查影像。','The scan showed a small difference / between the brain’s left hemisphere / and right hemisphere / so the neurologist requested a follow-up image.','hemisphere 在此指大脑的左半球或右半球。','左右脑被分为两个半球，符合 s2。')],mistakes:[M('The brain’s left hemisphere was described as the entire brain with no corresponding right half.','The brain has left and right hemispheres, each forming one half.','hemisphere 指半球；左半球不是整个大脑。')],quiz:[Q('hemisphere',1,1,'The Northern Hemisphere is?','the half of Earth north of the equator','the whole planet including both poles','one side of a shoe heel','the half of Earth north of the equator','s1 指按赤道或经线划分的地球半部。'),Q('hemisphere',2,2,'The brain has a left and a right?','hemisphere','hectare','hearth','hemisphere','s2 指大脑半球。'),Q('hemisphere',3,3,'A cultural hemisphere may mean?','a broad region or half of an area of activity','a single neuron','a small phone number','a broad region or half of an area of activity','s3 可比喻某个活动或知识领域的一半、区域。'),Q('hemisphere',4,1,'The prefix hemi- means?','half','whole','high','half','hemi- 表示“半”。','word-formation')]});
D('hemlock',{etymology:E('Hemlock is an old English plant name with an uncertain deeper origin. It names the poisonous herb Conium and also a conifer of the genus Tsuga, or the wood of that tree.','hemlock'),contexts:[C('hemlock.s2','森林调查','The forester identified a stand of eastern hemlock, a conifer whose soft needles and drooping branches shaded the stream bank.','护林员辨认出一片东部铁杉林；这种针叶树柔软的针叶和下垂枝条为溪岸遮阴。','The forester identified a stand of eastern hemlock / a conifer / whose soft needles and drooping branches / shaded the stream bank.','hemlock 在此指铁杉属针叶树。','针叶和枝条特征对应 Tsuga 树种。')],mistakes:[M('The forester identified the conifer hemlock as a soft-stemmed garden herb with no needles or woody trunk.','The forester identified the hemlock as a conifer with needles and a woody trunk.','此处 hemlock 指针叶树，不是无木质茎的草本。')],quiz:[Q('hemlock',1,1,'One meaning of hemlock is a poisonous?','herbaceous plant','harmless household grain','telephone support line','herbaceous plant','s1 指毒芹属有毒草本。'),Q('hemlock',2,2,'Eastern hemlock is a?','coniferous tree','small nocturnal mammal','bird of prey','coniferous tree','s2 指铁杉属针叶树。'),Q('hemlock',3,1,'Which caution is appropriate around poisonous hemlock?','do not ingest unknown plants','use it as ordinary salad without identification','assume every plant called hemlock is edible','do not ingest unknown plants','不应食用未确认的野生植物。'),Q('hemlock',4,2,'The wood of a Tsuga tree may also be called?','hemlock','hemp','hearth','hemlock','该词也可指针叶树木材。')]});
D('hemp',{etymology:E('Hemp comes from Old English hænep and related Germanic forms, ultimately borrowed from an ancient source. It names cannabis grown for tough fibre, seed, or oil; some varieties are also used as a drug.','hemp'),contexts:[C('hemp.s1','纺织工艺','The workshop softened hemp fibres and twisted them into durable cord for repairing the sail, keeping the material separate from food crops.','工坊把大麻纤维软化并搓成耐用绳索，用于修补船帆，同时将其与粮食作物分开存放。','The workshop softened hemp fibres / and twisted them into durable cord / for repairing the sail / keeping the material separate from food crops.','hemp 在此指用于生产坚韧纤维的工业大麻。','纤维被加工成绳索，体现其纤维用途。')],mistakes:[M('The sail cord was made from hemp, a delicate fibre that breaks immediately under any pulling force.','The sail cord was made from hemp, a tough fibre suitable for durable rope.','hemp 纤维以坚韧著称，不是轻轻一拉就断。')],quiz:[Q('hemp',1,1,'Hemp is grown for?','tough fibre, seed, or oil','the fruit of a conifer only','a ship’s steering wheel','tough fibre, seed, or oil','hemp 可用于纤维、种子和油料。'),Q('hemp',2,1,'Hemp fibre can be used to make?','strong cord or rope','a glass helmet','a hemlock leaf','strong cord or rope','坚韧纤维可制绳索。'),Q('hemp',3,1,'Some varieties of hemp are also used as?','a drug','a cooking temperature','a land unit','a drug','词义还包括部分品种的药物用途。'),Q('hemp',4,1,'Which crop is cultivated for durable plant fibre?','hemp','hen','heather','hemp','hemp 可产坚韧植物纤维。')]});
D('hen',{etymology:E('Hen comes from Old English henn, from a Germanic root. It usually means an adult female chicken and can also refer to a female bird of another kind.','hen'),contexts:[C('hen.s2','鸟类观察','The wildlife guide called the adult female grouse a hen and distinguished it from the brighter-plumed male nearby.','野生动物指南把那只成年雌松鸡称为 hen，并将它与附近羽色更鲜艳的雄鸟区分开来。','The wildlife guide called the adult female grouse a hen / and distinguished it / from the brighter-plumed male / nearby.','hen 在此泛指雌性鸟类，不限于母鸡。','雌松鸡属于 s2 的其他雌鸟用法。')],mistakes:[M('The guide called the male grouse a hen while noting that it laid the eggs and had the female plumage.','The guide called the female grouse a hen and the male a cock.','描述雄性鸟却称作 hen 与性别不符。')],quiz:[Q('hen',1,1,'A hen is usually an adult female?','chicken','horse','fish','chicken','s1 指成年母鸡。'),Q('hen',2,2,'The word hen can also refer to?','a female bird such as a grouse','a male rooster only','a young fish','a female bird such as a grouse','s2 可泛指其他雌鸟。'),Q('hen',3,1,'A farm hen may lay?','eggs','hemp fibres','telephone handsets','eggs','母鸡会产蛋。'),Q('hen',4,1,'Which bird could be called a hen in a broad sense?','an adult female pheasant','a male eagle','a hedgehog','an adult female pheasant','雌性鸟类可泛称 hen。')]});
D('hence',{etymology:E('Hence comes from Old English heonan, “from here.” It developed the meanings “for this reason” and “from this time onward.”','hence'),contexts:[C('hence.s1','实验结论','The sample had been exposed to sunlight for weeks; hence, its colour was lighter than the control kept in a dark cabinet.','样本已暴露在阳光下数周；因此，它的颜色比存放在暗柜中的对照样本更浅。','The sample had been exposed to sunlight for weeks / hence / its colour was lighter / than the control kept in a dark cabinet.','hence 在此连接原因与结果，表示“因此”。','长期光照解释了颜色变浅的结果。')],mistakes:[M('The sample was kept in darkness for weeks; hence, it faded because sunlight had bleached it.','The sample was kept in darkness for weeks; hence, it did not fade from sunlight.','长期处于黑暗却归因于阳光漂白，因果不成立。')],quiz:[Q('hence',1,1,'“The road was flooded; hence, we turned back” means?','for this reason, we turned back','from that time onward, the road flooded','we turned back before the flood','for this reason, we turned back','s1 表示因此。'),Q('hence',2,2,'“Henceforth” is related to hence in the sense of?','from this time onward','for this reason only','from the other side of the Earth','from this time onward','s2 表示从此以后。'),Q('hence',3,1,'Which sentence uses hence to give a result?','The lab was closed; hence, the test was postponed.','Hence the lab opens next month, perhaps.','The result is hence a question mark.','The lab was closed; hence, the test was postponed.','后半句是前半句导致的结果。'),Q('hence',4,1,'Hence is a formal alternative to?','therefore','however','beforehand','therefore','表示因果时 hence 接近 therefore。')]});
D('henceforth',{etymology:E('Henceforth combines hence, “from here or this time,” with forth, “forward.” It means starting now and continuing into the future; it is especially common in formal writing.','henceforth'),contexts:[C('henceforth.s2','正式通告','The notice stated that henceforth all visitors must register at the east entrance before entering the research building.','通告声明，从此以后所有访客进入研究楼前都必须在东门登记。','The notice stated / that henceforth all visitors must register / at the east entrance / before entering the research building.','henceforth 在此表示自公告发布之时起并持续下去。','新规定从现在起开始执行，符合 s2。')],mistakes:[M('The notice said henceforth the rule applied only last year and would not continue after today.','The notice said the rule applied last year but would not continue henceforth.','仅适用于过去、不延续至未来，与 henceforth 相反。')],quiz:[Q('henceforth',1,1,'Henceforth means?','from now on and continuing','only for a moment in the past','for this reason alone','from now on and continuing','henceforth 表示今后、从此以后。'),Q('henceforth',2,2,'In an official notice, henceforth often signals?','a rule begins now and remains in effect','an old rule has ended permanently','a reason is being given','a rule begins now and remains in effect','正式文本用该词宣布规则从此生效。'),Q('henceforth',3,1,'Which sentence uses henceforth correctly?','Henceforth, staff must wear badges at the entrance.','Henceforth, staff wore badges last week only.','The badge henceforth because the door is blue.','Henceforth, staff must wear badges at the entrance.','该词可置于句首说明新规今后执行。','grammar'),Q('henceforth',4,1,'A similar phrase to henceforth is?','from this point forward','for that reason','at the same time yesterday','from this point forward','意思接近 from this point forward。')]});
D('henderson',{etymology:E('Henderson is a family name, especially associated with Scotland and English-speaking countries. It is commonly interpreted as a patronymic meaning “son of Henry,” though the history of any individual bearer may differ.','henderson'),contexts:[C('henderson.s1','人物档案','The archive filed the letters under Henderson, the family name printed on the envelope and recorded in the donor’s catalogue entry.','档案馆把信件归入 Henderson 名下；这个姓氏印在信封上，也记录在捐赠者目录条目中。','The archive filed the letters under Henderson / the family name printed on the envelope / and recorded / in the donor’s catalogue entry.','Henderson 在此作为姓氏使用。','目录按信封上记录的家族姓氏归档。')],mistakes:[M('The catalogue treated Henderson as the name of a chemical element rather than the family name on the envelope.','The catalogue treated Henderson as the family name printed on the envelope.','Henderson 是专名姓氏，不是化学元素名。')],quiz:[Q('henderson',1,1,'Henderson is most commonly used as?','a family name','a unit of land area','a type of liver disease','a family name','Henderson 常见作姓氏。'),Q('henderson',2,1,'A file under Henderson would likely contain?','records for someone with that surname','measurements of a heptagon','a ship’s steering wheel','records for someone with that surname','按姓氏归档可找到相关人物记录。'),Q('henderson',3,1,'The surname is especially associated with?','Scotland and English-speaking countries','ancient Greek astronomy only','a species of chicken','Scotland and English-speaking countries','该姓常见于苏格兰及英语国家。'),Q('henderson',4,1,'As a proper name, Henderson should usually?','begin with a capital letter','be written only in lowercase','take a plural ending in every use','begin with a capital letter','专有姓氏首字母大写。','capitalization')]});
D('hepatitis',{etymology:E('Hepatitis is formed from Greek hēpar, “liver,” and -itis, “inflammation.” It names a disease involving inflammation of the liver; viral forms include hepatitis A, B, and C.','hepatitis'),contexts:[C('hepatitis.s1','公共卫生','The clinic brochure explains that hepatitis is inflammation of the liver and lists where residents can find reliable information about screening.','诊所宣传册说明肝炎是肝脏发炎，并列出居民获取可靠筛查信息的渠道。','The clinic brochure explains / that hepatitis is inflammation of the liver / and lists / where residents can find reliable information about screening.','hepatitis 指肝脏炎症性疾病。','释义直接说明炎症部位是肝脏。')],mistakes:[M('The brochure described hepatitis as inflammation of the lungs and directed patients to a lung-only screening clinic.','The brochure described hepatitis as inflammation of the liver and directed readers to appropriate health information.','hepatitis 的炎症部位是肝脏，不是肺部。')],quiz:[Q('hepatitis',1,1,'Hepatitis is inflammation of the?','liver','heart','skin only','liver','hepat- 指肝脏，-itis 指炎症。'),Q('hepatitis',2,1,'Which are recognized viral forms?','hepatitis A, B, and C','hepatitis North, East, and West','hepatitis 1, 2, and 9','hepatitis A, B, and C','常见病毒性肝炎类型包括 A、B、C。'),Q('hepatitis',3,1,'The suffix -itis in a medical term often means?','inflammation','a person who helps','a measurement of land','inflammation','-itis 常表示炎症。','word-formation'),Q('hepatitis',4,1,'A reliable description of hepatitis should identify the affected organ as the?','liver','heel','hemisphere','liver','肝炎影响肝脏。')]});
D('heptagon',{etymology:E('Heptagon combines Greek hepta, “seven,” with gōnia, “angle.” It names a polygon with seven sides and seven angles.','heptagon'),contexts:[C('heptagon.s1','几何课堂','The students drew a regular heptagon and checked that its seven sides were equal before calculating the interior angles.','学生们画了一个正七边形，并在计算内角前检查七条边是否相等。','The students drew a regular heptagon / and checked that its seven sides were equal / before calculating / the interior angles.','heptagon 指有七条边、七个角的多边形。','图形边数与角数都为七，符合定义。')],mistakes:[M('The worksheet called a six-sided polygon a heptagon even though one side and one angle were missing.','The worksheet called the six-sided polygon a hexagon.','六边形不是七边形。')],quiz:[Q('heptagon',1,1,'A heptagon has how many sides?','seven','six','eight','seven','hepta 表示七。','word-formation'),Q('heptagon',2,1,'A regular heptagon has?','seven equal sides and seven angles','five sides and seven angles','seven curved edges and no angles','seven equal sides and seven angles','正七边形有七条等长边和七个角。'),Q('heptagon',3,1,'Which shape is a heptagon?','a polygon with seven sides','a circle','a six-sided polygon','a polygon with seven sides','heptagon 是七边形。'),Q('heptagon',4,1,'The word heptagon combines a number meaning seven with a word for?','angle','height','bird','angle','-gon relates to angles.','word-formation')]});
D('her',{etymology:E('Her comes from Old English hire. It is a possessive form meaning belonging to a female person or animal, and also the object form of the pronoun she.','her'),contexts:[C('her.s2','句法教学','The nurse thanked her after the volunteer returned the lost wallet, using her as the object of the verb thanked.','志愿者归还了失物钱包后，护士向她道谢；这里 her 是动词 thanked 的宾语。','The nurse thanked her / after the volunteer returned the lost wallet / using her / as the object of the verb thanked.','her 在此是 she 的宾格形式，作 thanked 的宾语。','“thanked her”中 her 接在及物动词之后。')],mistakes:[M('The nurse thanked she after the volunteer returned the wallet.','The nurse thanked her after the volunteer returned the wallet.','及物动词 thanked 后应使用宾格 her，而不是主格 she。')],quiz:[Q('her',1,1,'“Her coat is blue” uses her to show?','the coat belongs to a female person','the coat is being thanked','the speaker is the object','the coat belongs to a female person','s1 表示属于女性或雌性动物。'),Q('her',2,2,'In “I called her,” her is?','the object form of she','the subject form of she','a possessive adjective','the object form of she','s2 是 she 的宾格形式。','grammar'),Q('her',3,2,'Choose the correct sentence.','The teacher spoke to her.','The teacher spoke to she.','Her spoke to the teacher.','The teacher spoke to her.','介词 to 后使用宾格 her。','grammar'),Q('her',4,1,'“The cat licked her paw” means the paw belongs to?','the female cat','the speaker only','another object','the female cat','her 可表示属于雌性动物。')]});
D('herald',{etymology:E('Herald came through Old French heraut, a messenger or official announcer; its deeper origin is uncertain. It can mean signal that something is coming, announce publicly, name a historical messenger, or a sign of what is to come.','herald'),contexts:[C('herald.s4','季节观察','The first crocuses were a herald of spring, appearing in the garden before most trees had begun to leaf.','最早开放的番红花预示着春天；它们在大多数树木长叶前就出现在花园里。','The first crocuses were a herald of spring / appearing in the garden / before most trees / had begun to leaf.','herald 在此作名词，指预示某事即将到来的迹象。','早花是春天将至的信号，符合 s4。')],mistakes:[M('The first crocuses were a herald of winter even though they appeared only after summer had ended.','The first crocuses were a herald of spring because they appeared as the season began.','春季初花预示春天，不是冬天。')],quiz:[Q('herald',1,1,'Dark clouds may herald?','an approaching storm','a completed harvest in the past','a type of phone call','an approaching storm','s1 作动词表示预示即将发生。'),Q('herald',2,2,'To herald a new policy is to?','announce it publicly','hide it from everyone','measure it in hectares','announce it publicly','s2 指公开宣布。'),Q('herald',3,3,'A herald in the past was a person who?','carried or announced messages','made protective helmets','measured the sky','carried or announced messages','s3 指历史上的传令官。'),Q('herald',4,4,'An early blossom can be a herald of?','spring','a legal inheritance','a liver disease','spring','s4 指即将到来的事物的迹象。')]});
D('herb',{etymology:E('Herb came through Old French from Latin herba, “grass or plant.” It can mean a plant used to flavour food, one used medicinally, or a soft-stemmed plant that dies back each year.','herb'),contexts:[C('herb.s3','植物识别','The botanist classified the soft-stemmed mint as an herbaceous herb because it died back in winter and regrew in spring.','植物学家把这种柔软茎秆的薄荷归为草本植物，因为它冬季枯萎、春天重新生长。','The botanist classified the soft-stemmed mint / as an herbaceous herb / because it died back in winter / and regrew in spring.','herb 在此指每年地上部分枯萎、茎不木质化的草本植物。','季节性枯萎并重新生长符合 s3。')],mistakes:[M('The botanist called the mint an herbaceous herb even though it had a permanent woody trunk and thick branches.','The botanist classified the mint as a woody shrub because it had a permanent trunk and branches.','常年木质主干不符合此处 herb 的草本义。')],quiz:[Q('herb',1,1,'Basil is often used as an herb to?','flavour food','steer a ship','measure a hemisphere','flavour food','s1 指用于调味的植物。'),Q('herb',2,2,'Some herbs are traditionally used?','as medicinal plants','as protective helmets','as area units','as medicinal plants','s2 指药用植物。'),Q('herb',3,3,'A botanical herb usually has?','a soft stem that dies back each year','a thick permanent woody trunk','a hard metal stalk','a soft stem that dies back each year','s3 指茎柔软、季节性枯萎的植物。'),Q('herb',4,1,'Which herb might be added to soup for flavour?','thyme','hemlock wood','a heptagon','thyme','百里香是常见烹饪香草。')]});
D('herbaceous',{etymology:E('Herbaceous is formed from herb plus -aceous, from Latin herba. It describes plants with soft, non-woody stems, in contrast with shrubs and trees.','herbaceous'),contexts:[C('herbaceous.s1','园艺分类','The herbaceous border was replanted with perennials whose stems died down in winter and returned from the roots each spring.','草本花境重新种上了多年生植物；它们的茎冬季枯萎，每年春天又从根部生长出来。','The herbaceous border was replanted with perennials / whose stems died down in winter / and returned from the roots / each spring.','herbaceous 描述茎不木质化、冬季地上部分枯萎的植物。','植物从根部返生且茎柔软，符合定义。')],mistakes:[M('The oak was herbaceous because its thick woody trunk remained above ground through every winter.','The oak was woody rather than herbaceous because it kept its trunk year-round.','有常年木质树干的橡树不是 herbaceous。')],quiz:[Q('herbaceous',1,1,'A herbaceous plant has?','soft, non-woody stems','a permanent woody trunk','metal branches','soft, non-woody stems','herbaceous 指草本、茎非木质。'),Q('herbaceous',2,1,'Which plant is most likely herbaceous?','a perennial that dies back in winter','an oak tree with a lasting trunk','a conifer with woody branches','a perennial that dies back in winter','冬季地上茎枯萎的多年生植物符合草本特征。'),Q('herbaceous',3,1,'Herbaceous contrasts with?','woody','helpful','helical','woody','该词与木本植物相对。'),Q('herbaceous',4,1,'The suffix -aceous helps form an adjective meaning?','having the nature of or relating to','without','a person who sells','having the nature of or relating to','-aceous 构成性质相关形容词。','word-formation')]});
D('herbal',{etymology:E('Herbal is formed from herb plus -al. It means made from or relating to herbs used in cooking or traditional medicine.','herbal'),contexts:[C('herbal.s1','饮品说明','The café served a caffeine-free herbal infusion made with mint leaves, lemon balm, and hot water.','咖啡馆供应一种不含咖啡因的草本浸泡饮，由薄荷叶、香蜂草和热水制成。','The café served a caffeine-free herbal infusion / made with mint leaves / lemon balm / and hot water.','herbal 修饰 infusion，表示由草本植物制成。','饮品以薄荷和香蜂草等草本为原料。')],mistakes:[M('The herbal tea contained no herbs or plant ingredients and was made only from metal filings.','The herbal tea was made from plant ingredients such as mint and lemon balm.','没有植物成分的饮料不能称为 herbal。')],quiz:[Q('herbal',1,1,'An herbal tea is made from?','herbs or other plant ingredients','metal filings','a ship’s helm','herbs or other plant ingredients','herbal 表示草本制成或与草本有关。'),Q('herbal',2,1,'A herbal remedy is connected with?','medicinal herbs','a legal heir','a heptagon','medicinal herbs','herbal 也可指与草药有关。'),Q('herbal',3,1,'Which phrase uses herbal correctly?','an herbal infusion of mint','a herbal hectare of land','a herbal heartbeat monitor','an herbal infusion of mint','薄荷浸泡饮是草本饮品。'),Q('herbal',4,1,'The suffix -al in herbal forms?','an adjective relating to herbs','a plural noun','a past-tense verb','an adjective relating to herbs','-al 构成相关形容词。','word-formation')]});
D('herbalist',{etymology:E('Herbalist is formed from herbal plus -ist, a suffix naming a person connected with a practice or field. It means someone who practises herbal medicine or sells medicinal herbs.','herbalist'),contexts:[C('herbalist.s1','草药店铺','The herbalist labeled each jar with the plant’s name and source, and advised customers to check safety information before using any preparation.','草药师给每个罐子贴上植物名称和来源标签，并提醒顾客使用任何制剂前先查看安全信息。','The herbalist labeled each jar / with the plant’s name and source / and advised customers / to check safety information before using any preparation.','herbalist 指从事草药实践或销售药用植物的人。','标注草药并提供使用信息，符合该职业义。')],mistakes:[M('The herbalist advised customers to ignore every plant label and assume all wild plants are safe to consume.','The herbalist advised customers to identify plants carefully and check reliable safety information.','鼓励不辨识野生植物可能造成危险，不是负责任的草药实践。')],quiz:[Q('herbalist',1,1,'A herbalist works with?','herbs used in traditional medicine or sold as remedies','helicopter engines','heptagons','herbs used in traditional medicine or sold as remedies','herbalist 指草药从业者或销售者。'),Q('herbalist',2,1,'A careful herbalist should?','identify plants and communicate safety information','claim every plant is harmless','remove all labels','identify plants and communicate safety information','草药从业者应谨慎识别并提供安全信息。'),Q('herbalist',3,1,'The suffix -ist often identifies?','a person connected with a practice','a unit of measurement','a type of plant stem','a person connected with a practice','-ist 常指某领域从业者。','word-formation'),Q('herbalist',4,1,'Which place might employ a herbalist?','a shop specializing in medicinal herbs','a helicopter landing pad','a ship’s engine room','a shop specializing in medicinal herbs','草药店可能由 herbalist 经营或供职。')]});
D('herbicide',{etymology:E('Herbicide combines herb with -cide, from Latin caedere, “to kill.” It names a chemical used to kill unwanted plants; the related word herbicide can also mean the act of using such chemicals.','herbicide'),contexts:[C('herbicide.s1','园林管理','The grounds team used a labeled herbicide only on the invasive weeds along the fence and followed the product directions to protect nearby plants.','园林团队只在围栏边的入侵杂草上使用有标签的除草剂，并遵照产品说明保护附近植物。','The grounds team used a labeled herbicide / only on the invasive weeds along the fence / and followed the product directions / to protect nearby plants.','herbicide 指用于杀灭不需要植物的化学物质。','句中把除草剂限定用于特定杂草，并按说明操作。')],mistakes:[M('The grounds team called a fertilizer that encouraged every plant to grow a herbicide.','The grounds team called the weed-killing chemical a herbicide.','herbicide 用于杀灭不需要的植物，不是促进植物生长的肥料。')],quiz:[Q('herbicide',1,1,'A herbicide is a chemical used to?','kill unwanted plants','feed livestock','seal an airtight jar','kill unwanted plants','herbicide 是除草剂。'),Q('herbicide',2,2,'In “Herbicide use was restricted,” herbicide refers to?','the use of chemicals to clear weeds','a group of plant-eating animals','a family inheritance','the use of chemicals to clear weeds','s2 指使用化学品清除杂草这一行为。'),Q('herbicide',3,1,'Which item is a herbicide?','a weed-killing chemical','a plant-eating mammal','a garden watering can','a weed-killing chemical','除草剂是杀灭杂草的化学制剂。'),Q('herbicide',4,1,'The suffix -cide is associated with?','killing','inheritance','a place or point','killing','-cide 与杀灭有关。','word-formation')]});
D('herbivore',{etymology:E('Herbivore combines Latin herba, “plant or grass,” with vorare, “to devour.” It names an animal that feeds on plants and, in food-chain discussion, the consumer group of plant-eaters.','herbivore'),contexts:[C('herbivore.s1','野生动物观察','The field guide identifies the deer as a herbivore because its diet consists mainly of leaves, grasses, and other plants.','野外指南把鹿归为食草动物，因为它的食物主要是树叶、青草和其他植物。','The field guide identifies the deer as a herbivore / because its diet consists mainly of leaves / grasses / and other plants.','herbivore 指以植物为主要食物的动物。','鹿的食谱以植物为主，符合食草动物的定义。')],mistakes:[M('The guide called the lion a herbivore because it hunted and ate other animals.','The guide called the lion a carnivore because it eats other animals.','herbivore 吃植物；捕食其他动物的是 carnivore。')],quiz:[Q('herbivore',1,1,'A herbivore mainly eats?','plants','other animals','metallic minerals','plants','herbivore 是食草动物。'),Q('herbivore',2,2,'In a food-chain diagram, herbivores are?','plant-eating consumers','the plants themselves','predators that eat only meat','plant-eating consumers','食物链中的 herbivores 是食草消费者。'),Q('herbivore',3,1,'Which animal is most clearly a herbivore?','a deer feeding on leaves','a hawk catching mice','a seal eating fish','a deer feeding on leaves','鹿以植物为食。'),Q('herbivore',4,1,'The element vor- in herbivore relates to?','eating or devouring','a written document','a point in space','eating or devouring','词根 vorare 表示吞食。','word-formation')]});
D('herbivorous',{etymology:E('Herbivorous is formed from herbivore plus -ous, an adjective-forming suffix. It describes an animal that lives on plants or a feature adapted to a plant-based diet.','herbivorous'),contexts:[C('herbivorous.s1','动物学讲解','The herbivorous mammals in the reserve browse on grasses and leaves, while the carnivores hunt other animals.','保护区内的草食性哺乳动物啃食青草和树叶，而食肉动物捕猎其他动物。','The herbivorous mammals in the reserve / browse on grasses and leaves / while the carnivores / hunt other animals.','herbivorous 描述以植物为食的动物。','句中草食动物吃草叶，与捕食动物形成对照。')],mistakes:[M('The report called a fish-eating seal herbivorous even though its diet contained no plants.','The report called the seal carnivorous because it eats fish.','只吃鱼的海豹不是 herbivorous。')],quiz:[Q('herbivorous',1,1,'An herbivorous animal lives mainly on?','plants','meat','letters and documents','plants','herbivorous 表示食草的。'),Q('herbivorous',2,2,'Herbivorous teeth or digestion are adapted for?','processing plant material','hunting with wings','writing formal notices','processing plant material','s2 指适应消化植物的特征。'),Q('herbivorous',3,1,'Which phrase is correct?','herbivorous deer','herbivorous steak-eating tiger','herbivorous metal tools','herbivorous deer','鹿是食草动物。'),Q('herbivorous',4,1,'The suffix -ous turns herbivore into?','an adjective','a plural verb','a place name','an adjective','-ous 常构成形容词。','word-formation')]});
D('herculean',{etymology:E('Herculean comes from Hercules, the Roman name of the Greek hero Heracles, famed for his strength and labors. It describes exceptional strength or a task demanding extraordinary effort.','herculean'),contexts:[C('herculean.s1','社区工程','Restoring the storm-damaged footbridge was a herculean task, requiring months of coordinated work by engineers and volunteers.','修复被风暴损坏的人行桥是一项艰巨任务，需要工程师和志愿者协同工作数月。','Restoring the storm-damaged footbridge / was a herculean task / requiring months of coordinated work / by engineers and volunteers.','herculean 在此形容异常艰巨、需要巨大努力的任务。','修桥耗时数月并需多人协作，体现任务艰巨。')],mistakes:[M('The crew called replacing one loose screw a herculean task even though it took a few seconds.','The crew reserved herculean for an undertaking requiring exceptional effort.','普通的几秒钟小事不符合 herculean 所含的巨大难度。')],quiz:[Q('herculean',1,1,'A herculean task is?','extremely difficult and demanding','easy to finish in seconds','a written family record','extremely difficult and demanding','herculean 常形容艰巨任务。'),Q('herculean',2,2,'A herculean athlete is described as having?','extraordinary physical strength','a plant-based diet','a sealed vocabulary','extraordinary physical strength','s2 指非凡的身体力量。'),Q('herculean',3,1,'Which project sounds herculean?','rebuilding a bridge after a major flood','opening a small envelope','choosing a seat in an empty room','rebuilding a bridge after a major flood','重大洪灾后的桥梁重建需要巨大努力。'),Q('herculean',4,1,'The adjective herculean refers by name to?','the hero Hercules','a seven-sided polygon','a female chicken','the hero Hercules','该词源自赫拉克勒斯的名字。','word-formation')]});
D('herd',{etymology:E('Herd comes from Old English heord, “a group of domestic animals.” As a noun it names an animal group or, figuratively, a crowd; as a verb it means to keep, drive, or gather a group.','herd'),contexts:[C('herd.s3','牧场工作','At dusk, the ranchers herd the cattle through the open gate and count them before closing the pasture.','黄昏时，牧场工人把牛群赶过敞开的栅门，并在关闭牧场前清点数量。','At dusk / the ranchers herd the cattle through the open gate / and count them / before closing the pasture.','herd 在此作动词，表示把一群牲畜赶到一起或赶向某处。','牧场工人赶牛穿过栅门，体现动词用法。')],mistakes:[M('The rancher herded each cow away from the others and left the group scattered across the road.','The rancher herded the cattle together through the gate.','herd 作动词通常表示聚集、照看或驱赶成群动物。')],quiz:[Q('herd',1,1,'A herd of bison is?','a large group of bison','one young plant','a sealed container','a large group of bison','herd 作名词可指一群同类动物。'),Q('herd',2,2,'A “herd mentality” refers figuratively to?','people following a crowd without much independent judgment','a family title passed down','an airtight glass jar','people following a crowd without much independent judgment','s2 比喻盲目随众的人群行为。'),Q('herd',3,3,'In “They herd sheep into the pen,” herd means?','drive or keep the animals together','admire a brave person','pass traits to offspring','drive or keep the animals together','herd 作动词表示赶拢或照管牲畜。'),Q('herd',4,4,'In “The tourists herded toward the exit,” the group?','gathered or moved together','became a chemical weed killer','inherited a title','gathered or moved together','s4 表示人群聚集或成群移动。')]});
D('herder',{etymology:E('Herder is formed from herd plus -er, a suffix naming a person who performs an action or occupation. It means someone who tends farm animals.','herder'),contexts:[C('herder.s1','牧区生活','The herder checked the sheep at the hillside enclosure before leading them back to the village for the night.','牧人把羊带回村里过夜前，先在山坡围栏处清点羊群。','The herder checked the sheep / at the hillside enclosure / before leading them back to the village / for the night.','herder 指照料并带领牲畜的人。','清点并带领羊群回村是牧人的工作。')],mistakes:[M('The article called a person who only repairs radios a herder, though the person never tends animals.','The article called the person who tends sheep a herder.','herder 的职业义与照料牲畜有关。')],quiz:[Q('herder',1,1,'A herder tends?','farm animals','heptagons','sealed letters','farm animals','herder 指牧人或牲畜照料者。'),Q('herder',2,1,'Which task fits a herder?','guiding sheep to pasture','measuring a hemisphere','writing a will','guiding sheep to pasture','带羊去牧场符合 herder 的工作。'),Q('herder',3,1,'The suffix -er in herder identifies?','a person who does an activity','a condition passed through genes','a type of animal food','a person who does an activity','-er 可构成表示从业者或施事者的名词。','word-formation'),Q('herder',4,1,'A herder would most likely work with?','a flock of sheep','a row of glass jars','a set of seven angles','a flock of sheep','牧人常照料羊群等牲畜。')]});
D('herdsman',{etymology:E('Herdsman combines herd with man, an older occupational compound for someone who tends a herd of cattle, sheep, or other livestock.','herdsman'),contexts:[C('herdsman.s1','乡村记述','The herdsman brought the cattle to the water trough and checked the fence before the animals returned to the pasture.','牧人把牛带到饮水槽，并在牛群回到牧场前检查围栏。','The herdsman brought the cattle to the water trough / and checked the fence / before the animals returned / to the pasture.','herdsman 指照料牛、羊等成群牲畜的人。','赶牛饮水并检查围栏，符合牧人的职责。')],mistakes:[M('The story called a person tending only a library collection a herdsman.','The story called the person tending the cattle a herdsman.','herdsman 的对象是畜群，不是书籍。')],quiz:[Q('herdsman',1,1,'A herdsman looks after?','livestock in a herd','a fleet of aircraft','a legal doctrine','livestock in a herd','herdsman 是牧人。'),Q('herdsman',2,1,'Which scene features a herdsman?','someone guiding cattle across a pasture','someone sealing a laboratory flask','someone drawing a seven-sided polygon','someone guiding cattle across a pasture','照料并带领牛群是牧人的工作。'),Q('herdsman',3,1,'The compound herdsman is built from?','herd + man','herb + island','here + after','herd + man','该词由 herd 与 man 构成。','word-formation'),Q('herdsman',4,1,'A herdsman would most likely check?','the livestock and pasture fence','a helical staircase','a family inheritance document','the livestock and pasture fence','牲畜与牧场围栏与牧人工作相关。')]});
D('here',{etymology:E('Here comes from Old English hēr, “in this place.” It can point to a location, movement toward the speaker, draw attention, or mark a point in time or an argument.','here'),contexts:[C('here.s3','会议现场','“Here,” said the librarian, pointing to the missing signature on the form, “is the field we still need to complete.”','图书管理员指着表格上缺失的签名说：“这里就是我们还需要填写的栏目。”','“Here,” said the librarian / pointing to the missing signature on the form / “is the field / we still need to complete.”','here 在此用于引起注意，指出某个具体位置或事项。','说话人用 here 指向表格上待填写的栏目。')],mistakes:[M('The speaker used here to mean a distant place where neither person was present.','The speaker used here while pointing to the form in front of them.','here 通常指说话者所在或当前谈论的位置、事项。')],quiz:[Q('here',1,1,'In “The keys are here,” here means?','in or at this place','from this time onward','a herd of cattle','in or at this place','s1 表示在此处。'),Q('here',2,2,'In “Come here,” here indicates movement?','to this place','away from this place','through a sealed container','to this place','s2 表示朝说话者所在处移动。'),Q('here',3,3,'A speaker saying “Here is the problem” uses here to?','draw attention to something','describe a plant-eating animal','name a religious doctrine','draw attention to something','s3 可用于引出并指出事项。'),Q('here',4,4,'“Here in the final section, we compare the results” uses here to mark?','a point in a discussion','a group of animals','a plant-killing chemical','a point in a discussion','s4 可标记论述中的位置。')]});
D('hereafter',{etymology:E('Hereafter combines here with after. It means from this time onward or, in religious contexts, life after death.','hereafter'),contexts:[C('hereafter.s1','正式声明','The agreement states that hereafter all schedule changes must be confirmed in writing by both parties.','协议规定，从今以后所有日程变更都必须由双方书面确认。','The agreement states / that hereafter / all schedule changes must be confirmed in writing / by both parties.','hereafter 在此表示从现在起、今后。','协议规定后续变更适用的新要求。')],mistakes:[M('The notice said the new rule applied only yesterday and would not continue hereafter.','The notice said the new rule would apply from now on.','hereafter 表示此后、从今以后，不是仅指过去某一天。')],quiz:[Q('hereafter',1,1,'In a policy, hereafter usually means?','from now on','at this place','by means of this letter','from now on','hereafter 可表示从今以后。'),Q('hereafter',2,1,'Which sentence uses hereafter correctly?','Hereafter, requests must include a reference number.','Hereafter means the chair is under the table.','They hereaftered the cattle through the gate.','Hereafter, requests must include a reference number.','正式通知可用 hereafter 引出今后适用的规则。'),Q('hereafter',3,1,'Hereafter is formed from?','here + after','herb + eater','heir + ship','here + after','该副词由 here 与 after 组合。','word-formation'),Q('hereafter',4,1,'In some religious writing, the hereafter can mean?','life after death','the present room','a plant-based diet','life after death','hereafter 也可指来世。')]});
D('hereby',{etymology:E('Hereby combines here with by. In formal declarations and documents, it means by this statement or document, and can also mean by this means.','hereby'),contexts:[C('hereby.s1','合同文本','The board hereby appoints Mira Chen as interim chair, with the decision recorded in the signed resolution.','董事会特此任命陈米拉为临时主席，该决定记录在签署的决议中。','The board hereby appoints Mira Chen as interim chair / with the decision recorded / in the signed resolution.','hereby 在此表示“通过本声明”或“特此”。','任命通过当前决议作出，符合正式文件用法。')],mistakes:[M('The contract used hereby to refer to an unrelated action completed by another document years earlier.','The contract used hereby to make the present declaration.','hereby 通常指通过当前陈述或文件来实施某事。')],quiz:[Q('hereby',1,1,'In a formal notice, hereby means?','by this statement or document','at the next village','a person who tends livestock','by this statement or document','hereby 常用于正式文件，表示特此。'),Q('hereby',2,2,'“The instrument is hereby certified” means it is certified?','by means of this instrument','at a later time only','by a group of plant eaters','by means of this instrument','s2 表示通过此文件或凭此。'),Q('hereby',3,1,'Which context most often uses hereby?','a formal declaration','a casual description of lunch','a field guide to birds','a formal declaration','hereby 常见于法律或正式文书。'),Q('hereby',4,1,'Hereby combines?','here + by','herd + boy','herb + berry','here + by','该词由 here 与 by 构成。','word-formation')]});
D('hereditary',{etymology:E('Hereditary comes through Latin hereditarius, “pertaining to inheritance,” from hereditas, “inheritance.” It describes traits transmitted through genes or titles and positions passed down in a family.','hereditary'),contexts:[C('hereditary.s1','遗传学课程','The report describes the condition as hereditary because evidence shows that the relevant gene variant can be passed from parent to child.','报告把这种状况描述为遗传性的，因为证据显示相关基因变异可以由父母传给子女。','The report describes the condition as hereditary / because evidence shows / that the relevant gene variant can be passed / from parent to child.','hereditary 在此表示通过基因由父母传给后代的。','句中说明变异经亲子传递，符合遗传义。')],mistakes:[M('The article called a brief fever caused by yesterday’s cold weather hereditary.','The article called a condition hereditary only when it can be passed through family inheritance or genes.','短暂受凉发热本身不能据此称为 hereditary。')],quiz:[Q('hereditary',1,1,'A hereditary trait is passed?','from parents to children through genes','from one desk to another','only by a signed letter','from parents to children through genes','hereditary 的一义是经基因遗传的。'),Q('hereditary',2,2,'A hereditary title is?','passed down within a family','caused by a plant-eating diet','sealed against all air','passed down within a family','s2 可形容家族世袭的头衔或职位。'),Q('hereditary',3,1,'Which example is hereditary in the family sense?','a title inherited across generations','a temporary rain shower','a weed-killing chemical','a title inherited across generations','家族中代代相传的头衔符合世袭义。'),Q('hereditary',4,1,'Hereditary is most closely related to?','inheritance','herding','a seven-sided shape','inheritance','该词与 inheritance（继承、遗传）相关。','word-formation')]});
D('heredity',{etymology:E('Heredity is formed from hereditary with the noun-forming suffix -ity. It names the biological process by which living things pass characteristics to their offspring, and the inherited qualities themselves.','heredity'),contexts:[C('heredity.s1','生物学教材','The chapter explains heredity by tracing how certain characteristics are passed from parents to offspring across generations.','本章通过追踪某些特征如何代代由父母传给后代来解释遗传。','The chapter explains heredity / by tracing how certain characteristics are passed / from parents to offspring / across generations.','heredity 在此表示生物特征由亲代传给后代的过程。','跨代传递特征描述了遗传过程。')],mistakes:[M('The lesson defined heredity as a person’s learned accent, acquired only after moving abroad.','The lesson defined heredity as the passing of biological characteristics between generations.','后天学会的口音不是此处所说的生物遗传。')],quiz:[Q('heredity',1,1,'Heredity is the process of?','passing characteristics from parents to offspring','driving cattle through a gate','sealing a container','passing characteristics from parents to offspring','heredity 指遗传过程。'),Q('heredity',2,2,'Heredity can also refer to?','qualities passed from parents to children','a document attached to a letter','a seven-sided polygon','qualities passed from parents to children','s2 指遗传下来的特征。'),Q('heredity',3,1,'Which field studies heredity?','genetics','road engineering','hermetic philosophy only','genetics','遗传学研究遗传及其规律。'),Q('heredity',4,1,'The ending -ity in heredity helps form?','a noun naming a state or process','a plural pronoun','a verb meaning to herd','a noun naming a state or process','-ity 常构成抽象名词。','word-formation')]});
D('herein',{etymology:E('Herein combines here with in. In formal writing it means in this document, place, or situation.','herein'),contexts:[C('herein.s1','文件阅读','The policy states that the terms defined herein apply to every department using the shared archive.','政策规定，本文所定义的条款适用于使用共享档案库的每个部门。','The policy states / that the terms defined herein / apply to every department / using the shared archive.','herein 在此表示“本文中”或“在本文件内”。','terms defined herein 指在当前政策中定义的条款。')],mistakes:[M('The reader treated herein as an instruction to search a distant town outside the document.','The reader treated herein as referring to information within the document.','herein 在正式写作中通常指本文或当前语境内。')],quiz:[Q('herein',1,1,'In a contract, herein usually means?','in this document','from now on','through this tool','in this document','herein 常指在本文或本文件中。'),Q('herein',2,1,'Which phrase is natural?','The rights described herein belong to the members.','The cattle herein across the field loudly.','She herein the parcel yesterday.','The rights described herein belong to the members.','rights described herein 指本文中所述的权利。'),Q('herein',3,1,'Herein combines?','here + in','herd + rain','heir + ship','here + in','该词由 here 与 in 组合。','word-formation'),Q('herein',4,1,'A cross-reference saying “as explained herein” points to?','an explanation in the current text','a herd beyond the hills','a plant-killing product','an explanation in the current text','herein 指当前文本内部。')]});
D('heresy',{etymology:E('Heresy comes through Latin from Greek hairesis, “choice” or “school of thought.” In religious or institutional contexts it names an opinion that strongly conflicts with accepted doctrine.','heresy'),contexts:[C('heresy.s1','宗教史研讨','The historian used heresy to describe a doctrine that church authorities judged to contradict the accepted teaching of the period.','历史学家用 heresy 描述一种被教会权威判定为违背当时公认教义的学说。','The historian used heresy / to describe a doctrine / that church authorities judged / to contradict the accepted teaching of the period.','heresy 指与某教会或权威所接受信仰相冲突的观点。','教义被判定违背当时的公认教导，符合其历史语境。')],mistakes:[M('The article called an ordinary disagreement over lunch heresy without any accepted doctrine or authority involved.','The historian reserved heresy for a serious conflict with an accepted religious or institutional doctrine.','heresy 通常涉及与既定教义或权威信念的严重冲突。')],quiz:[Q('heresy',1,1,'Heresy is an opinion that conflicts with?','accepted doctrine of a church or authority','a livestock feeding schedule','a family title','accepted doctrine of a church or authority','heresy 指违背既定教义的观点。'),Q('heresy',2,1,'A historian studying heresy would examine?','doctrines judged to oppose accepted teaching','how to grow a seven-sided flower','how a flask is sealed','doctrines judged to oppose accepted teaching','宗教史中的 heresy 涉及被视为异端的教义。'),Q('heresy',3,1,'Which disagreement is most likely called heresy?','a teaching rejected by a religious authority as contrary to doctrine','a preference for tea over coffee','a spelling difference in a shopping list','a teaching rejected by a religious authority as contrary to doctrine','与权威教义相冲突的教导最符合该词义。'),Q('heresy',4,1,'The Greek source hairesis originally related to?','choice or a school of thought','a plant-eating mammal','a place in a document','choice or a school of thought','希腊词源原与选择或思想学派有关。','word-formation')]});
D('herewith',{etymology:E('Herewith combines here with with. In formal correspondence it means along with this letter or document.','herewith'),contexts:[C('herewith.s1','商务函件','Please find herewith the signed inventory and the receipt for the returned equipment.','随函附上已签署的清单以及退还设备的收据。','Please find herewith / the signed inventory / and the receipt / for the returned equipment.','herewith 在此表示“随函附上”。','清单与收据和当前函件一并寄出。')],mistakes:[M('The email said herewith but sent no attachment and referred to a package arriving next month.','The email used herewith for documents attached to the current message.','herewith 指随同当前函件附上，不是遥指将来的包裹。')],quiz:[Q('herewith',1,1,'In a letter, herewith means?','along with this letter','in this chapter','from this moment forward','along with this letter','herewith 常用于表示随函附上。'),Q('herewith',2,1,'Which sentence uses herewith naturally?','I submit herewith the completed application.','The herdsman herewith the sheep yesterday.','The herbivore is herewith because it eats grass.','I submit herewith the completed application.','正式提交文件时可用 herewith 表示随文附上。'),Q('herewith',3,1,'Herewith combines?','here + with','herb + witch','hero + earth','here + with','该副词由 here 与 with 组合。','word-formation'),Q('herewith',4,1,'A document sent herewith should be?','included with the current letter or message','sent only after several years','a group of grazing animals','included with the current letter or message','herewith 指与当前函件同时附送。')]});
D('heritage',{etymology:E('Heritage came through Old French heritage from Latin hereditas, “inheritance.” It means traditions and culture passed down from the past, and can also refer to historically protected buildings or land.','heritage'),contexts:[C('heritage.s1','地方文化','The festival celebrates the town’s maritime heritage through oral histories, traditional songs, and an exhibit of old fishing tools.','这个节日通过口述历史、传统歌曲和旧渔具展览来庆祝小镇的海洋文化遗产。','The festival celebrates the town’s maritime heritage / through oral histories / traditional songs / and an exhibit of old fishing tools.','heritage 在此指从过去传承下来的文化与传统。','口述历史、歌曲和工具共同呈现小镇的传统文化。')],mistakes:[M('The brochure called a brand-new plastic sign the town’s centuries-old heritage despite its recent installation.','The brochure described the historic traditions and artifacts passed down by the town as its heritage.','刚安装的新塑料牌本身不是历经传承的文化遗产。')],quiz:[Q('heritage',1,1,'A community’s heritage includes?','traditions and culture passed down from the past','only this week’s weather','a chemical used to kill weeds','traditions and culture passed down from the past','heritage 可指代代相传的传统文化。'),Q('heritage',2,2,'A heritage site may be?','a historically protected building or area','a newly purchased lunchbox','a group of plant-eating animals','a historically protected building or area','s2 指受保护的历史建筑或土地。'),Q('heritage',3,1,'Which is an example of cultural heritage?','traditional songs preserved across generations','a temporary traffic cone','a sealed laboratory jar','traditional songs preserved across generations','代代保存的传统歌曲属于文化遗产。'),Q('heritage',4,1,'Heritage is historically connected with the idea of?','inheritance from the past','herding cattle','a place pointed to by here','inheritance from the past','该词源与继承有关。','word-formation')]});
D('hermaphrodite',{etymology:E('Hermaphrodite comes from Greek Hermaphroditos, the name of a figure in myth. In biology it describes an organism with both male and female reproductive structures; the adjective has the same biological sense.','hermaphrodite'),contexts:[C('hermaphrodite.s1','生物学课堂','The biology text explains that an earthworm is a hermaphrodite because an individual has both male and female reproductive structures.','生物教材说明蚯蚓是雌雄同体生物，因为单个个体同时具有雄性和雌性生殖结构。','The biology text explains / that an earthworm is a hermaphrodite / because an individual has both male and female / reproductive structures.','hermaphrodite 在此作名词，指同时具有两类生殖结构的生物。','例句使用中性的生物学定义说明蚯蚓的特征。')],mistakes:[M('The caption called a species a hermaphrodite merely because all individuals were the same size.','The caption used hermaphrodite only for an organism with both male and female reproductive structures.','个体大小相同与雌雄生殖结构无关。')],quiz:[Q('hermaphrodite',1,1,'A biological hermaphrodite has?','both male and female reproductive structures','no reproductive structures of any kind','only a woody stem','both male and female reproductive structures','该生物学名词指具有两类生殖结构的生物。'),Q('hermaphrodite',2,2,'In “a hermaphrodite organism,” hermaphrodite describes?','having both male and female reproductive organs','living only in a desert','having seven sides','having both male and female reproductive organs','s2 是描述具有两类生殖器官的形容词用法。'),Q('hermaphrodite',3,1,'Which is a suitable example in biology?','an earthworm with both reproductive structures','a rock with two colors','a bird that eats only seeds','an earthworm with both reproductive structures','蚯蚓可作为具有两类生殖结构的生物学例子。'),Q('hermaphrodite',4,1,'Hermaphrodite comes from the name of?','a figure in Greek myth','an Old English word for a herd','a Latin suffix meaning “place”','a figure in Greek myth','词源来自希腊神话人物 Hermaphroditos。','word-formation')]});
D('hermetic',{etymology:E('Hermetic is linked to Hermes Trismegistus, the legendary author associated with alchemy. It describes an airtight seal and, by extension, something obscure or closed off, or related to alchemy.','hermetic'),contexts:[C('hermetic.s1','实验室操作','The technician fitted a new gasket to make the storage vessel hermetic and prevent air from entering the sample chamber.','技术员安装了新垫圈，使储存容器密封不透气，防止空气进入样品室。','The technician fitted a new gasket / to make the storage vessel hermetic / and prevent air / from entering the sample chamber.','hermetic 在此表示气密的、密封的。','垫圈阻止空气进入样品室，体现气密封闭。')],mistakes:[M('The container was described as hermetic even though its loose lid allowed air to circulate freely.','The container was hermetic only after the gasket stopped air from entering.','能让空气自由流通的容器不是 hermetic。')],quiz:[Q('hermetic',1,1,'A hermetic seal is?','airtight','open to free air flow','made from livestock feed','airtight','hermetic 可表示气密的。'),Q('hermetic',2,2,'A hermetic text may be?','obscure and closed off to outsiders','easy for every reader to understand','a herd of grazing cattle','obscure and closed off to outsiders','s2 可形容晦涩、封闭难懂的内容。'),Q('hermetic',3,1,'Which container is hermetic?','a jar sealed so air cannot enter','a basket with wide gaps','an uncovered bowl','a jar sealed so air cannot enter','气密罐可防止空气进入。'),Q('hermetic',4,2,'Hermetic is also associated historically with?','ancient alchemy','modern livestock farming only','the grammar of pronouns','ancient alchemy','该词也与古代炼金术传统相关。','word-formation')]});
D('hermit',{etymology:E('Hermit came through Latin eremita from Greek erēmītēs, “person of the desert.” It names someone who withdraws from other people, often for religious or contemplative reasons.','hermit'),contexts:[C('hermit.s1','人物传记','After years of public work, the writer became a hermit in a remote cottage, receiving only occasional visitors.','多年从事公共工作后，这位作家在偏远小屋隐居，只偶尔接待访客。','After years of public work / the writer became a hermit / in a remote cottage / receiving only occasional visitors.','hermit 指离群独居的人，常因宗教或沉思等原因隐居。','作家住在偏远小屋并少见访客，符合隐居者的特点。')],mistakes:[M('The biography called a social host who held large weekly parties a hermit.','The biography called the writer who withdrew to live alone a hermit.','经常主持大型社交聚会的人不符合 hermit 的离群独居义。')],quiz:[Q('hermit',1,1,'A hermit is someone who?','withdraws from other people and lives apart','tends a large herd for a living','passes a title to an heir','withdraws from other people and lives apart','hermit 指隐士或离群独居者。'),Q('hermit',2,1,'Which scene best fits a hermit?','a person living alone in a remote cabin','a crowded party host greeting hundreds','a team guiding cattle together','a person living alone in a remote cabin','独居偏远小屋符合隐士形象。'),Q('hermit',3,1,'The Greek source of hermit referred to a person of the?','desert','harbor','marketplace','desert','希腊语源与沙漠居住者有关。','word-formation'),Q('hermit',4,1,'A hermit might withdraw for religious or?','contemplative reasons','herbicide production','herd breeding','contemplative reasons','隐居也可能出于沉思等原因。')]});
D('hero',{etymology:E('Hero comes through Latin from Greek hērōs, “hero or demigod.” It names a person admired for courage or noble deeds, someone greatly admired, or the principal male character in a story.','hero'),contexts:[C('hero.s1','新闻报道','The firefighter became a local hero after carrying two residents to safety during the apartment fire.','公寓起火时，这名消防员把两位居民救到安全处，后来成为当地英雄。','The firefighter became a local hero / after carrying two residents to safety / during the apartment fire.','hero 在此指因勇敢行为而受到敬佩的人。','冒火救人体现勇气和高尚行为。')],mistakes:[M('The article called the person who abandoned the rescue effort a hero for showing no courage or concern.','The article called the firefighter a hero for rescuing residents at personal risk.','hero 的敬佩义与勇敢或高尚行为相关。')],quiz:[Q('hero',1,1,'A hero is often admired for?','courage or noble actions','sealing jars','eating only plants','courage or noble actions','hero 常指勇敢或做出高尚行为的人。'),Q('hero',2,2,'“My grandmother is my hero” means she is?','someone the speaker greatly admires','the main male character in a novel','a person who tends cattle','someone the speaker greatly admires','s2 表示个人非常敬佩的人。'),Q('hero',3,3,'In “The hero returns in chapter five,” hero means?','the main male character in the story','a weed-killing chemical','a family inheritance','the main male character in the story','s3 指故事中的主要男性角色。'),Q('hero',4,1,'The Greek source hērōs referred to a?','hero or demigod','seven-sided figure','plant-eating animal','hero or demigod','词源 hērōs 指英雄或半神。','word-formation')]});

})();
